import ImgBtn from '@/components/ImgBtn';
import ModeSwitch from '@/components/ModeSwitch';
import EditList from '@/pages/Agentic/EditList';
import SelectedCodeList from '@/pages/Agentic/SelectedCodeList';
import { useGlobalStore } from '@/store';
import { Input } from 'antd';
import { TextAreaRef } from 'antd/es/input/TextArea';
import classNames from 'classnames';
import { useEffect, useRef, useState } from 'react';
import Abort from '../Abort';
import ExpandPanel from '../ExpandPanel';
import ModelBtn from '../ModelBtn';
import ProviderPopover from '../ModelConfigPopOver';
import PreviewImg from '../PreviewImg';
import SendBtn from '../SendBtn';
import ExpandPanelTagList from './ExpandPanelTagList';
import styles from './index.module.less';
import CommandBtn from './ToolBar/CommandBtn';
import { ExpandPanelRef, ExpandPanelTag, ImageType } from './type';
import { processBase64Images } from './utils/imageUtils';

interface AgentUserInputProps {
  isModelShow?: boolean;
  loading: boolean;
  onAbort: () => void;
  placeHolder?: string;
  chatId: string;
  sendAgentQuestion: (
    inputValue: string,
    images: ImageType[],
    otherInfo: any,
  ) => void;
  tabRef?: React.MutableRefObject<any>;
}

const AgentUserInput: React.FC<AgentUserInputProps> = ({
  isModelShow = true,
  loading,
  onAbort,
  chatId,
  placeHolder = '请清晰描述您的需求',
  sendAgentQuestion,
  tabRef,
}) => {
  const {
    pluginConfig: { theme },
  } = useGlobalStore();
  const inputRef = useRef<TextAreaRef>(null);
  const prevValueRef = useRef<string>(''); // 存储输入框上一次的值
  const expandPanelValueRef = useRef<string>(''); // 存储扩展面板选中的字符串
  const expandPanelRef = useRef<ExpandPanelRef>(null);
  const inputAreaRef = useRef<HTMLDivElement>(null);
  const [expandPanelValidTagList, setExpandPanelValidTagList] = useState<
    Array<ExpandPanelTag>
  >([]); // 面板选中tag列表
  const [inputValue, setInputValue] = useState<string>('');
  const [isComposing, setIsComposing] = useState<boolean>(false);
  const [isFocused, setIsFocused] = useState<boolean>(false);

  const [expandPanelShow, setExpandPanelShow] = useState<boolean>(false);
  const [inputAreaHeight, setInputAreaHeight] = useState<number>(0);

  const [imgArr, setImgArr] = useState<Array<string>>([]);
  const [popoverOpen, setPopoverOpen] = useState(false);

  // 自动聚焦
  useEffect(() => {
    setTimeout(() => inputRef.current?.focus(), 100);

    // 监听输入框高度变化,为了实现拓展面板紧贴输入框
    if (!inputAreaRef.current) return;

    const observer = new ResizeObserver((entries) => {
      const { height } = entries[0].contentRect;
      setInputAreaHeight(height);
    });

    observer.observe(inputAreaRef.current);
    return () => observer.disconnect(); // 清理
  }, []);

  const onSendQuestion = (e?: React.MouseEvent) => {
    e?.preventDefault?.();
    e?.stopPropagation?.();
    if (!inputValue || loading) return;

    const images = processBase64Images(imgArr);

    sendAgentQuestion?.(
      inputValue,
      images,
      expandPanelValidTagList.length ? expandPanelValidTagList : null,
    );
    setInputValue('');
  };

  const onEnter = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (isComposing) return;

    if (event.key === 'Enter' && event.shiftKey) return;
    if (event.key === 'Enter' && !event.metaKey && !event.ctrlKey) {
      event.preventDefault();
      event.stopPropagation();
      // 当扩展面板打开时，回车键不触发发送，而是触发选中面板选项
      if (!expandPanelShow) {
        onSendQuestion();
      } else {
        // 回车键选中扩展面板的选项
        expandPanelRef.current?.pick();
      }
    }
    // 方向键控制扩展面板
    if (isFocused) {
      let isDown = event.key === 'ArrowDown';
      let isUp = event.key === 'ArrowUp';
      if ((isDown || isUp) && event.shiftKey) return;
      if ((isDown || isUp) && !event.metaKey && !event.ctrlKey) {
        if (isDown) {
          expandPanelRef.current?.down();
        } else {
          expandPanelRef.current?.up();
        }
        event.preventDefault();
        event.stopPropagation();
      }
    }
  };

  const onInputChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = event.target.value;
    if (
      value.length < prevValueRef.current.length && // 正在删除
      prevValueRef.current.includes(expandPanelValueRef.current) && // 原内容包含触发词
      !value.includes(expandPanelValueRef.current) // 新内容不再包含
    ) {
      setInputValue(''); // 清空输入框
      prevValueRef.current = '';
      setExpandPanelShow(false);
      return;
    } else {
      setInputValue(value);
    }
    // 监听输入框 如果用户输入@符号 唤起扩展面板 但需要判断是否已经输入了@符号
    const cursorPos = event.target.selectionStart || 0; // 检测是否是新输入的@
    const isNewAt =
      value[cursorPos - 1] === '@' && // 当前光标前是@
      !prevValueRef.current.includes('@'); // 之前没有@

    // 或者是第一个字符输入@
    const isFirstCharAt = value === '@' && prevValueRef.current === '';
    if (isNewAt || isFirstCharAt) {
      setExpandPanelShow(true);
    } else if (!value.includes('@')) {
      setExpandPanelShow(false);
      expandPanelValueRef.current = '';
    }
    prevValueRef.current = value; // 更新历史值
  };

  const onExpandPanelAbort = (
    str: string,
    close: boolean = false,
    data: { text: string; icon: () => React.ReactNode; value: any } = {} as any,
  ) => {
    let newstr = close ? `@${str} ` : `@${str}: `;
    // 面板关闭时 将艾特内容设置成标签
    if (close) {
      setInputValue('');
      setExpandPanelShow(false);
      setExpandPanelValidTagList([...expandPanelValidTagList, data]); // 要传给对话接口的数据
      expandPanelValueRef.current = '';
      prevValueRef.current = '';
    } else {
      const processedStr = str.trim();
      const shouldClear = !processedStr;
      const valueToSet = shouldClear ? '' : newstr;
      const sliceValue = shouldClear ? '' : newstr.slice(0, -1);
      setInputValue(valueToSet);
      expandPanelValueRef.current = sliceValue;
      prevValueRef.current = sliceValue;
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  const handleDelete = (index: number) => {
    // 创建新数组，排除指定索引的元素
    const newList = [...expandPanelValidTagList];
    newList.splice(index, 1);
    setExpandPanelValidTagList(newList);
  };

  return (
    <div className={styles.newUserInput}>
      {loading && <Abort onAbort={onAbort} chatId={chatId} />}
      {imgArr?.length > 0 && (
        <PreviewImg imgArr={imgArr} setImgArr={setImgArr} />
      )}
      <EditList />
      <SelectedCodeList />
      <ExpandPanel
        ref={expandPanelRef}
        showSwitch={expandPanelShow}
        position={inputAreaHeight}
        filterValue={inputValue}
        inputAreaRef={inputAreaRef}
        onAbort={onExpandPanelAbort}
        onClose={() => {
          setExpandPanelShow(false);
        }}
      />
      <div className={styles.footer}>
        <div ref={inputAreaRef} className={styles.outer}>
          {expandPanelValidTagList?.length > 0 && (
            <ExpandPanelTagList
              tags={expandPanelValidTagList}
              onDelete={handleDelete}
            />
          )}
          <div
            className={classNames(styles.inputContainer, {
              [styles.inputContainerDark]: theme === 'dark',
              [styles.inputContainerLight]: theme === 'light',
            })}
          >
            <Input.TextArea
              ref={inputRef}
              autoSize={{ minRows: 1, maxRows: 6 }}
              placeholder={placeHolder}
              value={inputValue}
              onChange={onInputChange}
              onKeyDown={onEnter}
              className={styles.input}
              onCompositionStart={() => setIsComposing(true)}
              onCompositionEnd={() => setIsComposing(false)}
              onFocus={() => setIsFocused(true)}
              onBlur={() => setIsFocused(false)}
            />
          </div>
          <div
            className={classNames(styles.toolBar, {
              [styles.toolBarDark]: theme === 'dark',
              [styles.toolBarLight]: theme === 'light',
            })}
          >
            <div className={styles.left}>
              <CommandBtn
                expandPanelShow={expandPanelShow}
                onToggle={() => setExpandPanelShow(!expandPanelShow)}
              />
              <ImgBtn
                setImgArr={setImgArr}
                imgArr={imgArr}
                chatId={chatId}
                tabRef={tabRef}
              />
            </div>
            <div className={styles.right}>
              <ModeSwitch />
              {isModelShow && (
                <ProviderPopover
                  open={popoverOpen}
                  onClose={() => setPopoverOpen(false)}
                  anchor={
                    <div onClick={() => setPopoverOpen(!popoverOpen)}>
                      <ModelBtn />
                    </div>
                  }
                />
              )}
              <div className={styles.sendBtnWrapper}>
                <SendBtn
                  loading={loading}
                  inputValue={inputValue}
                  onSendQuestion={onSendQuestion}
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AgentUserInput;
