import AgentUserInput from '@/components/AgentUserInput';
import BottomTips from '@/pages/Agentic/BottomTips';
import InitPage from '@/pages/InitPage';
import { agentRedo, uploadTotalHistoryData } from '@/services/Api/agentic';
import { useAgenticStore, useGlobalStore } from '@/store';
import { message } from 'antd';
import { useCallback, useEffect, useMemo } from 'react';
import { useAutoScroll } from '../Chat/ChatTab/hooks/useAutoScroll';
import Loading from './Loading';
import MsgItem from './MsgItem';
import { useUpdateEditFileList } from './MsgItem/hooks/useUpdateEditFileList';
import emitter from './eventBus';
import { ImageType, useAgentChat } from './hooks/useAgentChat';
import { useAgentEvents } from './hooks/useAgentEvents';
import { useAgentUrlParams } from './hooks/useAgentUrlParams';
import styles from './index.module.less';

const Agent: React.FC = () => {
  const { abortRef, chatId, loading, fetchHistory, onAbort, sendMessage } =
    useAgentChat();

  const {
    setChatId,
    isTokenOver,
    clearMessagesAfter,
    buttonStateMap,
    selectedMessageId,
    setSelectedMessageId,
    latestUserMessageId,
    setLatestUserMessageId,
    msgMap,
    setButtonState,
  } = useAgenticStore();

  const {
    projectConfig: {
      sideCarIDEInfo: { sideCarPort, rootDirectory },
    },
  } = useGlobalStore();

  const updateEditFileList = useUpdateEditFileList();

  // 自动滚动功能
  const { scrollContainerRef, scrollToBottom } = useAutoScroll();

  // 处理事件监听
  useAgentEvents();

  // 处理URL参数
  useAgentUrlParams(chatId, setChatId, fetchHistory);

  // 更新最新的用户消息ID
  useEffect(() => {
    const userMessages = Object.values(msgMap).filter(
      (msg) => msg.type === 'user',
    );
    if (userMessages.length > 0) {
      setLatestUserMessageId(userMessages[userMessages.length - 1].messageId);
    }
  }, [msgMap, setLatestUserMessageId]);

  // 当消息列表更新时，自动滚动到底部
  useEffect(() => {
    if (msgMap && Object.keys(msgMap).length > 0) {
      setTimeout(() => {
        scrollToBottom(true);
      }, 100);
    }
  }, [msgMap, scrollToBottom]);

  // 连接abort事件到abortRef
  useEffect(() => {
    const handleAbort = () => abortRef.current();
    emitter.on('abortRequest', handleAbort);
    return () => {
      emitter.off('abortRequest', handleAbort);
    };
  }, [abortRef]);

  const handleMessageSelect = (messageId: string) => {
    // 如果点击的是当前选中的消息，则取消选择
    setSelectedMessageId(selectedMessageId === messageId ? null : messageId);
  };

  // 处理蒙层点击事件
  const handleMaskClick = async () => {
    if (selectedMessageId) {
      // 获取当前选中消息的详细信息
      const selectedMessage = msgMap[selectedMessageId];
      if (selectedMessage && selectedMessage.exchangeId) {
        const { sideCarPort, projectId, editorUrl } =
          useGlobalStore.getState().projectConfig.sideCarIDEInfo;

        // 执行 redo 逻辑
        const { success, data } = await agentRedo(
          {
            session_id: chatId,
            exchange_id: `request_${selectedMessage.exchangeId}`,
            project_id: projectId,
            edit_url: editorUrl,
          },
          `http://localhost:${sideCarPort}`,
        );

        if (success) {
          // 更新按钮状态为 restore
          setButtonState(selectedMessageId, 'restore');
          // 清除选中的消息
          setSelectedMessageId(null);
          // 更新编辑文件列表
          updateEditFileList(data);
        } else {
          message.error('redo error');
        }
      } else {
        // 如果没有找到消息信息，只清除选中状态
        setSelectedMessageId(null);
      }
    }
  };

  // 包装后的发送消息函数
  const handleSendAgentQuestion = useCallback(
    async (inputValue: string, images: Array<ImageType>, otherInfo: any) => {
      if (selectedMessageId) {
        // 按钮状态变为 redo 说明此时是执行了 restore 操作
        const isRestoreState = buttonStateMap[selectedMessageId] === 'redo';
        const baseUrl = `http://localhost:${sideCarPort}`;

        if (isRestoreState) {
          clearMessagesAfter(selectedMessageId);
          // 上报文件列表的历史记录 - 获取最新状态
          const currentState = useAgenticStore.getState();
          uploadTotalHistoryData(
            {
              sessionId: chatId,
              uiData: JSON.stringify(currentState.msgMap),
              editFileList: currentState.editFileList,
              repoRef: `local/${rootDirectory || '/'}`,
            },
            baseUrl,
          ).then(() => {
            console.log('checkout 文件列表更新成功');
          });
        }
        setSelectedMessageId(null);
      }

      // 发送消息后自动滚动到底部
      setTimeout(() => {
        scrollToBottom(true);
      }, 100);

      sendMessage(inputValue, images, otherInfo);
    },
    [
      selectedMessageId,
      buttonStateMap,
      sideCarPort,
      clearMessagesAfter,
      chatId,
      rootDirectory,
      setSelectedMessageId,
      sendMessage,
      scrollToBottom,
    ],
  );

  const msgArray = Object.values(msgMap);

  // 计算哪些消息需要显示头像
  const messagesWithAvatar = useMemo(() => {
    const messages = Object.values(msgMap);
    const messagesWithAvatar = new Set<string>();

    for (let i = 0; i < messages.length; i++) {
      const currentMsg = messages[i];

      // 如果是 agent 消息，检查是否是用户询问后的第一条回复
      if (currentMsg.type === 'agent') {
        // 向前查找最近的一条用户消息
        let lastUserMessageIndex = -1;
        for (let j = i - 1; j >= 0; j--) {
          if (messages[j].type === 'user') {
            lastUserMessageIndex = j;
            break;
          }
        }

        // 如果找到了用户消息，检查当前 agent 消息是否是该用户消息后的第一条 agent 消息
        if (lastUserMessageIndex !== -1) {
          let isFirstAgentAfterUser = true;
          for (let j = lastUserMessageIndex + 1; j < i; j++) {
            if (messages[j].type === 'agent') {
              isFirstAgentAfterUser = false;
              break;
            }
          }

          if (isFirstAgentAfterUser) {
            messagesWithAvatar.add(currentMsg.messageId);
          }
        }
      }
    }

    return messagesWithAvatar;
  }, [msgMap]);

  return (
    <div className={styles.agentic}>
      <div className={styles.agentic_main}>
        <div ref={scrollContainerRef} className={styles.agentic_scrollToBottom}>
          {!msgArray.length && <InitPage />}
          {msgArray.map((item, index, array) => {
            const selectedIndex = selectedMessageId
              ? array.findIndex((msg) => msg.messageId === selectedMessageId)
              : -1;
            const isAfterSelected =
              selectedIndex !== -1 && selectedIndex < index;
            const isLastMessage = index === array.length - 1;
            return (
              <div
                key={item.messageId}
                className={isAfterSelected ? styles.maskedMessage : ''}
                onClick={isAfterSelected ? handleMaskClick : undefined}
              >
                <MsgItem
                  {...item}
                  onAbort={onAbort}
                  onSelect={handleMessageSelect}
                  isSelected={item.messageId === selectedMessageId}
                  isLastMessage={isLastMessage}
                  isLatestUserMessage={item.messageId === latestUserMessageId}
                  showAvatar={messagesWithAvatar.has(item.messageId)}
                />
              </div>
            );
          })}
          {loading && Object.values(msgMap).length > 0 && <Loading />}
        </div>
      </div>
      <div className={styles.agentic_input}>
        <AgentUserInput
          loading={loading}
          chatId={chatId}
          onAbort={onAbort}
          sendAgentQuestion={handleSendAgentQuestion}
        />
      </div>
      <div>
        <BottomTips isTokenOver={isTokenOver} />
      </div>
    </div>
  );
};

export default Agent;
