import { AgentMsgItem } from '@/pages/Agentic/type';
import { FC } from 'react';
import ReqCard from './ReqCard';
import RespCard from './RespCard';
import styles from './index.module.less';

interface MessageItemProps extends AgentMsgItem {
  showAvatar?: boolean;
  onSelect?: (messageId: string) => void;
  isSelected?: boolean;
  isLastMessage?: boolean;
  isLatestUserMessage?: boolean;
}

const MessageItem: FC<MessageItemProps> = (props) => {
  const {
    type,
    content,
    toolType,
    param,
    output,
    err,
    detect,
    onAbort,
    showAvatar = false,
    onSelect,
    isSelected,
    isLastMessage,
    isLatestUserMessage,
  } = props;

  return content ? (
    <div className={styles.messageItem}>
      {type === 'user' ? (
        <ReqCard
          {...props}
          onSelect={onSelect}
          isSelected={isSelected}
          isLastMessage={isLastMessage}
          isLatestUserMessage={isLatestUserMessage}
        />
      ) : (
        <RespCard
          message={content}
          toolType={toolType}
          param={param}
          detect={detect}
          output={output}
          err={err}
          onAbort={onAbort}
          showAvatar={showAvatar}
        />
      )}
    </div>
  ) : null;
};
export default MessageItem;
