import { ReactComponent as AddSVG } from '@/assets/footer/mcp.svg';
import { jsBridgePostMessageWithCallback } from '@/services/JsBridge/jsBridgePostMessage';
import { useGlobalStore } from '@/store';
import { CloseOutlined, RightOutlined } from '@ant-design/icons';
import { Switch } from 'antd';
import classNames from 'classnames';
import React, {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';
import styles from '../../index.module.less';
interface McpToolProps {
  list: any;
  show: boolean;
  theme: string;
}
interface McpToolInfo {
  status: string;
  serverName: string;
  tools: string[] | [];
  [key: string]: any;
}

const DEBOUNCE_DELAY = 300;

const McpTool: React.FC<McpToolProps> = forwardRef((props) => {
  const {
    pluginConfig: { ide: myIDE },
  } = useGlobalStore();
  const { list, show, theme } = props;
  const [debounceTimer, setDebounceTimer] = useState(null);
  const [toolShowTab, setToolShowTab] = useState<number>(0);
  const [newMcpList, setNewMcpList] = useState<McpToolInfo[]>([]); // MCP列表
  const [toolTipShowSwitch, setToolTipShowSwitch] = useState(false);
  const loadingRef = useRef<boolean>(false);

  useEffect(() => {
    setToolTipShowSwitch(false);
    setNewMcpList(list);
  }, [list]);

  const fetchAddMCP = useCallback(() => {
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }
    const timer: any = setTimeout(async () => {
      try {
        if (loadingRef.current) return;
        loadingRef.current = true;
        const res = await jsBridgePostMessageWithCallback({
          command: 'addMcpMarketServer',
          data: {},
        });
        loadingRef.current = false;
      } catch (error) {
        console.error('addMcpMarketServer 请求失败:', error);
      }
    }, DEBOUNCE_DELAY);

    setDebounceTimer(timer);
  }, [debounceTimer]);

  // 组件卸载时清除计时器
  useEffect(() => {
    return () => {
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }
    };
  }, [debounceTimer]);

  const fetchQhMCP = async (info: McpToolInfo) => {
    const status = info.status === 'ENABLED' ? 'DISABLED' : 'ENABLED';
    if (myIDE === 'jetbrains') {
      const res = await jsBridgePostMessageWithCallback({
        command: 'mcpStatusSwitch',
        data: {
          serverName: info.serverName,
          status,
        },
      });
    } else {
      const res = await jsBridgePostMessageWithCallback({
        command: 'noticeRefresh',
        data: {
          serverName: info.serverName,
          status,
        },
      });
    }
  };

  const handleSwitchChange = (item: McpToolInfo) => {
    const toolName: string = item.serverName;
    fetchQhMCP(item);
    if (item.status === 'DISABLED') {
      let othernum = newMcpList.reduce(
        (acc, tool: McpToolInfo) =>
          tool.status === 'ENABLED' ? acc + tool.tools.length : acc,
        0,
      );
      if (item.tools.length + othernum > 40) {
        setToolTipShowSwitch(true);
      }
    }
    setNewMcpList((prevList) =>
      prevList.map((tool) =>
        tool.serverName === toolName
          ? {
              ...tool,
              status: tool.status === 'ENABLED' ? 'DISABLED' : 'ENABLED',
            }
          : tool,
      ),
    );
  };
  return (
    <div
      style={{ position: 'relative', display: `${show ? 'block' : 'none'}` }}
    >
      {newMcpList?.map((item, index) => {
        const isok = item.status === 'ENABLED';
        const isno = item.status === 'DISABLED';
        return (
          <div
            key={index}
            style={{ borderColor: theme === 'dark' ? '#394250' : '#ddd' }}
            className={styles.expandCellOut}
          >
            <div className={classNames(styles.expandCell, styles.tool)}>
              <div className={classNames(styles.left, styles.lg)}>
                <Switch
                  className={styles.toolSwitch}
                  onChange={() => {
                    handleSwitchChange(item);
                  }}
                  checked={isok}
                  style={{
                    backgroundColor: isok ? '#5ec169' : '#4d5662',
                  }}
                  size="small"
                />
              </div>
              <div
                onClick={() => {
                  if (+index + 1 === toolShowTab) {
                    setToolShowTab(0);
                  } else {
                    setToolShowTab(index + 1);
                  }
                }}
                className={classNames(styles.right, styles.bet)}
              >
                <span
                  className={styles.name}
                  style={{ color: theme === 'dark' ? '#ccc' : '#000' }}
                >
                  {item.serverName}
                </span>
                <span
                  className={styles.path}
                  style={{ color: theme === 'dark' ? '#626262' : '#999' }}
                >
                  {isok && item.tools.length ? (
                    <strong className={classNames(styles.circle)} />
                  ) : null}
                  {isok && !item.tools.length ? (
                    <strong className={classNames(styles.circle, styles.red)} />
                  ) : null}
                  {isno ? (
                    <strong
                      className={classNames(styles.circle, styles.gray)}
                    />
                  ) : null}
                  <i>{item.tools?.length} tools</i>
                  <RightOutlined
                    style={{
                      marginLeft: '10px',
                      transform: `${
                        toolShowTab === +index + 1 ? `rotate(90deg)` : 'none'
                      }`,
                    }}
                  />
                </span>
              </div>
            </div>

            <div
              className={styles.toolDescContent}
              style={{
                display: `${+index + 1 === toolShowTab ? 'block' : 'none'}`,
              }}
            >
              {item.tools.map((mtool, mtoolIndex) => {
                return (
                  <div
                    key={mtoolIndex}
                    className={classNames(styles.toollDesc)}
                  >
                    <p className={styles.ttitle}>{mtool}</p>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
      <div
        className={classNames(styles.expandCell, styles.tool)}
        style={{ height: 30 }}
      >
        <span className={styles.wantadd} onClick={() => fetchAddMCP()}>
          <AddSVG style={{ marginRight: 12 }} /> 添加 MCP 服务
        </span>
      </div>
      <div
        className={styles.tooltip}
        style={{ display: `${toolTipShowSwitch ? 'flex' : 'none'}` }}
      >
        <div className={styles.tooltipleft}>
          <h3>警告</h3>
          <p>
            选中的服务总工具数（64），已超过40个上限。CodeLink目前不支持运行。
          </p>
        </div>
        <div
          onClick={() => {
            setToolTipShowSwitch(false);
          }}
          className={styles.tooltipright}
        >
          <CloseOutlined />
        </div>
      </div>
    </div>
  );
});
export default McpTool;
