import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { FC, ReactNode } from 'react';

const judgeLink = (href: string) => {
  const reg = /^https?:\/\/[^\s/$.?#].[^\s]*$/;
  return reg.test(href);
};

interface LinkRenderProps {
  href?: string;
  children: ReactNode & ReactNode[];
  className?: string;
  messageId?: string;
  componentCode?: string;
}

const LinkRender: FC<LinkRenderProps> = (props) => {
  const { href, children, className, messageId, componentCode } = props;

  const onClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (!href) return;
    const isWebLink = judgeLink(href);
    if (isWebLink) {
      jsBridgePostMessage({
        command: 'openBrowser',
        data: {
          url: href,
          messageId,
          componentCode,
        },
      });
    } else {
      jsBridgePostMessage({
        command: 'fileLinkage',
        data: {
          uri: href,
          messageId,
          componentCode,
        },
      });
    }
  };

  return (
    <a onClick={onClick} className={className}>
      {children}
    </a>
  );
};
export default LinkRender;
