import { ReactComponent as CollapseDarkSVG } from '@/assets/agent/collapse-dark.svg';
import { ReactComponent as CollapseLightSVG } from '@/assets/agent/collapse-light.svg';
import { ReactComponent as OpenDarkSVG } from '@/assets/agent/open-dark.svg';
import { ReactComponent as OpenLightSVG } from '@/assets/agent/open-light.svg';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useAgenticStore, useGlobalStore } from '@/store';
import parseGitDiff from '@/utils/parseGitDiff';
import { Button } from 'antd';
import classNames from 'classnames';
import React, { useEffect, useRef, useState } from 'react';
import styles from './index.module.less';
import ListItem from './ListItem';

export interface EditFileItem {
  fileName: string;
  addLine: number;
  deleteLine: number;
  oldContent: string;
  newContent: string;
  state?: 'accept' | 'reject' | null; // 新增状态字段
}

interface DiffMsgObj {
  old_content: string;
  new_content: string;
  session_old_content: string;
  file_path: string;
  diff: string;
  session_diff: string;
}

const EditList: React.FC = () => {
  const { editFileList, setEditFileList, addData } = useAgenticStore();
  const {
    pluginConfig: { theme, mode },
  } = useGlobalStore();
  const [isExpanded, setIsExpanded] = useState<boolean>(false);
  const hasMountedRef = useRef<boolean>(false);

  // 逻辑：追踪最新一张编辑卡，从而更新文件列表的状态
  useEffect(() => {
    if (!hasMountedRef.current) {
      hasMountedRef.current = true;
      return;
    }

    if (!Object.keys(addData)?.length) return;

    const obj: DiffMsgObj = JSON.parse(
      addData.output!.ToolOutputResponse.answer_up_until_now,
    );
    const diffResult = parseGitDiff(obj.session_diff);
    const fileName = addData.param!.tool_parameter_input.field_content_delta;

    const existingFile = editFileList.find(
      (file) => file.fileName === fileName,
    );

    const newItem = {
      fileName,
      addLine: diffResult.addedLines,
      deleteLine: diffResult.removedLines,
      oldContent: obj.session_old_content,
      newContent: obj.new_content,
      state: null,
    };

    if (!existingFile) {
      setEditFileList([...editFileList, newItem]);
    } else {
      setEditFileList(
        editFileList.map((file) =>
          file.fileName === fileName ? newItem : file,
        ),
      );
    }
  }, [addData]);

  const toggleExpand = () => setIsExpanded(!isExpanded);

  const totalFiles = editFileList.length;
  const totalAdditions = editFileList.reduce(
    (sum, item) => sum + item.addLine,
    0,
  );
  const totalDeletions = editFileList.reduce(
    (sum, item) => sum + item.deleteLine,
    0,
  );

  if (mode !== 'agent' || !totalFiles) return null;

  const handleAcceptAll = () => {
    // 过滤出状态为 null 的文件
    const filesToAccept = editFileList.filter((item) => item.state === null);

    if (filesToAccept.length === 0) return;

    const allFileNames = filesToAccept.map((item) => item.fileName);
    const allOldContents = filesToAccept.map((item) => item.oldContent);

    // 更新所有未处理文件的状态为 accept
    const updatedList: Array<EditFileItem> = editFileList.map((item) =>
      item.state === null ? { ...item, state: 'accept' } : item,
    );
    setEditFileList(updatedList);
    jsBridgePostMessage({
      command: 'accept',
      data: {
        fileName: allFileNames,
        oldContent: allOldContents,
      },
    });
  };

  const handleRejectAll = () => {
    // 过滤出状态为 null 的文件
    const filesToReject = editFileList.filter((item) => item.state === null);

    if (filesToReject.length === 0) return;

    const allFileNames = filesToReject.map((item) => item.fileName);
    const allOldContents = filesToReject.map((item) => item.oldContent);

    // 更新所有未处理文件的状态为 reject
    const updatedList: Array<EditFileItem> = editFileList.map((item) =>
      item.state === null ? { ...item, state: 'reject' } : item,
    );
    setEditFileList(updatedList);

    jsBridgePostMessage({
      command: 'reject',
      data: {
        fileName: allFileNames,
        oldContent: allOldContents,
      },
    });
  };

  return (
    <div className={styles.editListContainer}>
      <div className={styles.editSummary} onClick={toggleExpand}>
        <span className={styles.toggleIcon}>
          {isExpanded ? (
            theme === 'dark' ? (
              <CollapseDarkSVG />
            ) : (
              <CollapseLightSVG />
            )
          ) : theme === 'dark' ? (
            <OpenDarkSVG />
          ) : (
            <OpenLightSVG />
          )}
        </span>
        <span>编辑了 {totalFiles} 个文件</span>
        <span className={styles.addition}>+{totalAdditions}</span>
        <span className={styles.deletion}>-{totalDeletions}</span>
        {editFileList.filter((item) => item.state === null).length > 0 && (
          <div
            className={styles.actionButtons}
            onClick={(e) => e.stopPropagation()}
          >
            <Button size="small" onClick={handleRejectAll}>
              全部拒绝
            </Button>
            <Button size="small" onClick={handleAcceptAll}>
              全部接受
            </Button>
          </div>
        )}
      </div>
      <div
        className={classNames(styles.fileList, {
          [styles.collapsed]: !isExpanded,
        })}
      >
        {editFileList.map((item) => (
          <ListItem item={item} key={item.fileName} />
        ))}
      </div>
    </div>
  );
};

export default React.memo(EditList);
