import { getSessionId } from '@/services/Api/agentic';
import { useAgenticStore, useChatStore, useGlobalStore } from '@/store';
import { useCallback } from 'react';

export const useUnifiedNewChat = () => {
  const {
    setChatId,
    setMsgMap,
    setEditFileList,
    setAddData,
    setIsTokenOver,
    setSelectedCodeList,
  } = useAgenticStore();
  const { chatList, setChatList, setChatMessageList } = useChatStore();
  const {
    projectConfig: { sideCarIDEInfo },
  } = useGlobalStore();

  const createUnifiedNewChat = useCallback(async () => {
    if (!sideCarIDEInfo) {
      return null;
    }
    const { sideCarPort } = sideCarIDEInfo;

    try {
      // 为 agent 模式创建会话 ID
      const agentRes = await getSessionId(`http://localhost:${sideCarPort}`);
      if (!agentRes.success) {
        console.error('创建 agent 会话失败');
        return null;
      }
      // @ts-ignore
      const agentSessionId = agentRes.session_id;

      // 为 chat 模式创建会话 ID
      const chatRes = await getSessionId(`http://localhost:${sideCarPort}`);
      if (!chatRes.success) {
        console.error('创建 chat 会话失败');
        return null;
      }
      // @ts-ignore
      const chatSessionId = chatRes.session_id;

      // 更新agent模式的会话ID
      setChatId(agentSessionId);

      // 清空agent模式的消息数据
      setMsgMap({});
      setEditFileList([]);
      // @ts-ignore
      setAddData({});
      setIsTokenOver(false);
      setSelectedCodeList([]);

      // 更新chat模式的会话列表
      const newChatItem = {
        chatId: chatSessionId,
        chatType: 'new' as const,
        openTime: new Date().getTime(),
      };
      setChatList([newChatItem]);

      // 清空所有chat会话的消息数据
      if (chatList.length > 0) {
        chatList.forEach((chat) => {
          setChatMessageList(chat.chatId, []);
        });
      }

      // 确保新会话的消息列表为空
      setChatMessageList(chatSessionId, []);

      return {
        agentSessionId,
        chatSessionId,
      };
    } catch (error) {
      console.error('创建新会话失败:', error);
      return null;
    }
  }, [
    sideCarIDEInfo,
    setChatId,
    setChatList,
    setChatMessageList,
    setMsgMap,
    setEditFileList,
    setAddData,
    setIsTokenOver,
    setSelectedCodeList,
    chatList,
  ]);

  return {
    createUnifiedNewChat,
  };
};
