// useAgentChat.ts
import { useUnifiedNewChat } from '@/hooks/useUnifiedNewChat';
import { SelectedCodeItem } from '@/pages/Agentic/SelectedCodeList';
import { jsBridgePostMessageWithCallback } from '@/services/JsBridge/jsBridgePostMessage';
import { useAgenticStore, useGlobalStore } from '@/store';
import { ProviderType } from '@/store/Global/types';
import { sendAgentChat } from '@/utils/sendAgentChat/sendAgentChat';
import { UserContext } from '@/utils/sendAgentChat/type';
import { message } from 'antd';
import { noop } from 'lodash';
import { useCallback, useMemo, useRef } from 'react';
import { v4 as uuid } from 'uuid';
import { getModelName, modelConfig } from '../modelConfig';
import { useAgentMessageHandlers } from './useAgentMsgHandlers';
import { useChatSession } from './useChatSession';

export interface ImageType {
  type: string;
  media_type: string;
  data: string;
}

interface OtherInfoItem {
  key: string;
  value: string;
}

interface GlobalRule {
  type?: string;
  content?: string;
}

interface FilePosition {
  line: number;
  character: number;
  byteOffset: number;
}

interface FileItem {
  name: string;
  start_position: FilePosition;
  end_position: FilePosition;
  content: string;
  fs_file_path: string;
  type: string;
  language: string;
}

/**
 * 构建Agent聊天payload
 */
const buildAgentChatPayload = (
  chatId: string,
  exchangeId: string,
  inputValue: string,
  sideCarInfo: any,
  selectedCodeList: SelectedCodeItem[],
  modelName: string,
  otherInfo: OtherInfoItem[],
  globalRules: GlobalRule[],
  images: ImageType[],
  provider: ProviderType,
) => {
  const {
    editorUrl,
    rootDirectory,
    openFiles,
    shell,
    projectLabels,
    projectId,
  } = sideCarInfo;

  const prevChatHistories: string[] = []; // 历史对话
  const folderPaths: string[] = []; // 文件夹
  const files: FileItem[] = []; // 文件
  let aiteRules = ''; // 规则
  let aiteRulesNum = 1;

  if (globalRules.length) {
    globalRules.forEach((gi: GlobalRule) => {
      aiteRules += `${aiteRulesNum}.${gi.content || gi}`;
      aiteRulesNum++;
    });
  }

  if (otherInfo?.length) {
    otherInfo.forEach((_info: OtherInfoItem) => {
      if (_info?.key === 'PastChats') {
        prevChatHistories.push(_info.value);
      }
      if (_info?.key === 'Rules') {
        // 面板上选择的手动规则
        aiteRules = aiteRules + `${aiteRulesNum}.${_info.value}`;
        aiteRulesNum++;
      }
      if (_info?.key === 'Notepads') {
        // 记事本
        inputValue += ',' + _info.value;
      }
      if (_info?.key === 'Folders') {
        folderPaths.push(_info.value);
      }
      if (_info?.key === 'Files') {
        // @ts-ignore
        files.push(_info.value);
      }
    });
  }

  if (selectedCodeList?.length) {
    files.push(
      ...selectedCodeList.map((item) => ({
        name: item.name ?? '',
        start_position: {
          line: item.startLine,
          character: item.startOffset,
          byteOffset: 0,
        },
        end_position: {
          line: item.endLine,
          character: item.endOffset,
          byteOffset: 0,
        },
        content: item.fullContent,
        fs_file_path: item.fsPath,
        type: 'Selection',
        language: item.language,
      })),
    );
  }

  const userContext: UserContext = {
    variables: files,
    file_content_map: [],
    images: images || [],
    folder_paths: folderPaths,
    is_plan_generation: false,
    is_plan_execution_until: null,
    is_plan_append: false,
    with_lsp_enrichment: false,
    is_plan_drop_from: null,
  };

  return {
    session_id: chatId,
    exchange_id: `request_${exchangeId}`,
    editor_url: editorUrl || '',
    query: inputValue,
    root_directory: rootDirectory || '',
    project_labels: projectLabels || [],
    project_id: projectId || '',
    all_files: [],
    open_files: openFiles.filter(Boolean),
    shell: shell || '',
    aide_rules: aiteRules || '',
    reasoning: false,
    is_devtools_context: false,
    model_configuration: {
      ...modelConfig,
      slow_model: modelName,
      model_name: provider.model_name,
      selected_provider: provider.selected_provider,
      selected_provider_api_key: provider.selected_provider_api_key,
    },
    codebase_search: false,
    access_token: '',
    repo_ref: `local/${rootDirectory || '/'}`,
    agent_mode: '4',
    user_context: userContext,
    semantic_search: false,
    can_use_deploy: false,
    can_use_fix_bug: false,
    command_auto_run: false,
  };
};

export const useAgentChat = () => {
  const abortRef = useRef<() => void>(noop);

  const {
    selectedCodeList,
    agentModel,
    msgMap,
    addMessage,
    loading,
    setSelectedCodeList,
    chatId,
  } = useAgenticStore();

  const {
    projectConfig: { sideCarIDEInfo },
    pluginConfig: { emailPrefix, provider },
  } = useGlobalStore();

  // 使用统一的创建新会话方法
  const { createUnifiedNewChat } = useUnifiedNewChat();

  // 使用拆分出的 useChatSession 中的其他方法
  const { fetchExchangeId, fetchHistory } = useChatSession();

  // 使用拆分出的消息处理器
  const { onReceiveAgentMessage, onLoadingStatusChange, onError, onFinally } =
    useAgentMessageHandlers(chatId, sideCarIDEInfo, abortRef);

  // 获取模型名称
  const modelName = useMemo(() => getModelName(agentModel), [agentModel]);

  /**
   * 中止当前请求
   */
  const onAbort = useCallback(() => abortRef.current(), []);

  /**
   * 创建新会话的包装方法
   */
  const createNewChatAction = useCallback(async () => {
    return await createUnifiedNewChat();
  }, [createUnifiedNewChat]);

  /**
   * 发送消息给 Agent
   */
  const sendMessage = useCallback(
    async (
      inputValue: string,
      images: ImageType[],
      otherInfo: OtherInfoItem[],
    ) => {
      if (!sideCarIDEInfo) {
        message.warning('Agent 模式正在初始化中,请稍后再试');
        return;
      }

      const newExchangeId = await fetchExchangeId(chatId);
      if (!newExchangeId) {
        message.error('获取交换ID失败');
        return;
      }

      const { data: ruleData } = await jsBridgePostMessageWithCallback({
        command: 'ruleInfoReq',
        data: {},
      });

      /// 提取和处理规则
      const globalRule = ruleData?.globalRule || '';
      const projectRules = ruleData?.projectRule || [];

      const regularRules = [globalRule, ...projectRules]
        .filter((rule) => rule && rule.type !== 'MODEL_DECIDE')
        .map((rule) => rule.content || rule);

      // 构建payload
      const payload = buildAgentChatPayload(
        chatId,
        newExchangeId,
        inputValue,
        sideCarIDEInfo,
        selectedCodeList,
        modelName,
        otherInfo,
        regularRules,
        images,
        provider,
      );

      const messageId = uuid();
      addMessage({
        messageId,
        type: 'user',
        source: 'chat',
        chatId,
        exchangeId: newExchangeId,
        payload,
        content: inputValue,
        contexts: {
          selectedCodeList,
        },
      });

      setSelectedCodeList([]);

      if (!provider) {
        message.info('请先配置 API KEY 再使用哦～');
        return;
      }

      const { selected_provider, selected_provider_api_key } = provider;
      const obj = selected_provider_api_key?.[selected_provider];
      if (!obj || Object.keys(obj)?.length === 0) {
        message.info('请先配置 API KEY 再使用哦～');
        return;
      }

      // 发送聊天请求
      sendAgentChat({
        chatId,
        sideCarPort: sideCarIDEInfo.sideCarPort,
        emailPrefix: emailPrefix || '',
        payload,
        onReceiveAgentMessage,
        onError,
        onLoadingStatusChange,
        onFinally,
        abortRef,
      });
    },
    [
      chatId,
      sideCarIDEInfo,
      provider,
      selectedCodeList,
      modelName,
      addMessage,
      fetchExchangeId,
      onReceiveAgentMessage,
      onError,
      onLoadingStatusChange,
      onFinally,
      emailPrefix,
      agentModel,
      setSelectedCodeList,
    ],
  );

  return {
    abortRef,
    msgMap,
    chatId,
    loading,
    provider,
    createNewChatAction,
    fetchHistory,
    onAbort,
    sendMessage,
  };
};
