/**
 * 解析Git Diff格式字符串，计算增加和减少的行数
 * @param diffContent Git Diff格式的字符串
 * @returns 包含增加行数和减少行数的对象
 */
export default (
  diffContent: string,
): { addedLines: number; removedLines: number } => {
  let addedLines = 0;
  let removedLines = 0;

  const lines = diffContent.split('\n');

  lines.forEach((line) => {
    // 忽略diff头部信息行（以---、+++或@@开头的行）
    if (
      line.startsWith('---') ||
      line.startsWith('+++') ||
      line.startsWith('@@')
    ) {
      return;
    }

    // 计算增加的行（以+开头但不是+++）
    if (line.startsWith('+')) addedLines++;
    // 计算删除的行（以-开头但不是---）
    else if (line.startsWith('-')) removedLines++;
  });

  return { addedLines, removedLines };
};
