import { ReactComponent as AddSVG } from '@/assets/footer/mcp.svg';
import { ReactComponent as NotePadSVG } from '@/assets/footer/notepad.svg';
import { jsBridgePostMessageWithCallback } from '@/services/JsBridge/jsBridgePostMessage';
import { Popover } from 'antd';
import classNames from 'classnames';
import React, {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import styles from '../../index.module.less';
interface NotepadsProps {
  list: any;
  show: boolean;
  theme: string;
  inputValue: string;
  onParentPick: (item: {
    key: string;
    text: string;
    value: string;
    icon: () => React.ReactNode;
  }) => void;
  ref: any;
}

interface NotepadsInfo {
  fileContent: string;
  fileName: string;
}

const TitlePop = (text = '') => (
  <div>
    <p>{text}</p>
  </div>
);

const RightLine = ({
  isActive = false,
  name = '',
  sub = '',
  popOver = '',
  theme = '',
}) => {
  let activeColor = theme === 'dark' ? '#fff' : '#000';
  let dfcolor = theme === 'dark' ? '#ccc' : '#000';
  let textColor = isActive ? activeColor : dfcolor;
  let subColor = theme === 'dark' ? (isActive ? '#adadad' : '#626262') : '#999';
  return (
    <>
      <div className={styles.left} style={{ color: textColor }}>
        <NotePadSVG />
      </div>
      <div className={styles.right}>
        {popOver ? (
          <Popover content={() => TitlePop(popOver)} title={name}>
            <span className={styles.name} style={{ color: textColor }}>
              {name}
            </span>
          </Popover>
        ) : (
          <span className={styles.name} style={{ color: textColor }}>
            {name}
          </span>
        )}
        {sub ? (
          <span className={styles.path} style={{ color: subColor }}>
            {sub}
          </span>
        ) : null}
      </div>
    </>
  );
};

const filterList = (list: NotepadsInfo[], searchTerm: string) => {
  if (!searchTerm.trim() || searchTerm.length < 3) return list; // 无搜索词时直接返回原列表
  const lowerCaseSearchTerm = searchTerm.toLowerCase();
  return list.filter((item) => {
    const nameMatch = item.fileName
      ?.toLowerCase()
      .includes(lowerCaseSearchTerm);
    const contentMatch = item.fileContent
      ?.toLowerCase()
      .includes(lowerCaseSearchTerm);
    return nameMatch || contentMatch;
  });
};

const Notepads: React.FC<NotepadsProps> = forwardRef((props, ref) => {
  const { list, show, inputValue, onParentPick, theme } = props;
  const contentRef = useRef<HTMLDivElement>(null);
  const highLightLineRef = useRef<HTMLElement[]>([]);
  const stopMouseEnter = useRef<boolean>(false);
  const [selectedLine, setSelectedLine] = useState<number>(0);
  const filterNewList = useMemo(
    () => filterList(list, inputValue),
    [list, inputValue],
  );
  const [debounceTimer, setDebounceTimer] = useState(null);
  const loadingRef = useRef<boolean>(false);

  const fetchAdd = useCallback(() => {
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }
    const timer: any = setTimeout(async () => {
      try {
        if (loadingRef.current) return;
        loadingRef.current = true;
        const res = await jsBridgePostMessageWithCallback({
          command: 'addNotepad',
          data: {},
        });
        loadingRef.current = false;
      } catch (error) {
        console.error('addNotepad 请求失败:', error);
      }
    }, 300);

    setDebounceTimer(timer);
  }, [debounceTimer]);

  // 组件卸载时清除计时器
  useEffect(() => {
    return () => {
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }
    };
  }, [debounceTimer]);

  useEffect(() => {
    stopMouseEnter.current = true;
    if (filterNewList.length > 0) {
      setSelectedLine(0); // 设置为第一行
    }
    setTimeout(() => (stopMouseEnter.current = false), 100);
  }, [filterNewList]); // 监听过滤结果的变化

  const checkCurrentLineIsVisible = (currentLine: number) => {
    let item = highLightLineRef.current[currentLine];
    let container = contentRef.current;
    if (!container || !item) return;
    const itemTop = item.offsetTop;
    const containerHeight = container.clientHeight;
    const itemHeight = item.offsetHeight;
    const scrollTop = container.scrollTop;
    if (itemTop < scrollTop) {
      container.scrollTop = itemTop;
    } else if (itemTop + itemHeight > scrollTop + containerHeight) {
      container.scrollTop = itemTop + itemHeight - containerHeight;
    }
  };

  const selfPick = () => {
    onParentPick({
      key: 'Notepads',
      text: filterNewList[selectedLine].fileName,
      value: filterNewList[selectedLine].fileContent,
      icon: () => <NotePadSVG />,
    });
  };

  const down = () => {
    stopMouseEnter.current = true;
    let nextLine = selectedLine;
    if (selectedLine >= filterNewList.length - 1) {
      nextLine = 0;
    } else {
      nextLine = selectedLine + 1;
    }
    setSelectedLine(nextLine);
    checkCurrentLineIsVisible(nextLine);
    setTimeout(() => (stopMouseEnter.current = false), 100);
  };

  const up = () => {
    stopMouseEnter.current = true;
    let nextLine = selectedLine;
    if (nextLine <= 0) {
      nextLine = filterNewList.length - 1;
    } else {
      nextLine = selectedLine - 1;
    }
    setSelectedLine(nextLine);
    checkCurrentLineIsVisible(nextLine);
    setTimeout(() => (stopMouseEnter.current = false), 100);
  };

  const handleMouseEnter = (index: number) => {
    if (stopMouseEnter.current) return;
    setSelectedLine(index);
  };

  useImperativeHandle(ref, () => ({
    pick: selfPick,
    down: down,
    up: up,
  }));

  return show ? (
    <div
      ref={contentRef}
      className={classNames(styles.maxheight300, styles.pb26)}
    >
      {filterNewList?.map((item, index) => {
        return (
          <div
            ref={(el) => {
              if (el) highLightLineRef.current[index] = el;
            }}
            className={classNames(
              styles.expandCell,
              selectedLine === index ? styles.active : '',
            )}
            onMouseEnter={() => handleMouseEnter(+index)}
            onClick={() => {
              selfPick();
            }}
            key={index}
          >
            <RightLine
              isActive={selectedLine === index}
              theme={theme}
              name={item.fileName}
              popOver={item.fileContent}
            />
          </div>
        );
      })}
      <div
        style={{ borderColor: theme === 'dark' ? '#394250' : '#ddd' }}
        className={classNames(styles.expandCell, styles.ottool)}
      >
        <span
          className={styles.wantadd}
          onClick={() => {
            fetchAdd();
          }}
        >
          <AddSVG style={{ marginRight: 12 }} /> 添加 Notepads
        </span>
      </div>
    </div>
  ) : null;
});
export default Notepads;
