import { ReactComponent as CommonFileDarkSVG } from '@/assets/agent/common-file-dark.svg';
import { ReactComponent as CommonFileLightSVG } from '@/assets/agent/common-file-light.svg';
import { ReactComponent as CssDarkSVG } from '@/assets/agent/css-dark.svg';
import { ReactComponent as CssLightSVG } from '@/assets/agent/css-light.svg';
import { ReactComponent as HtmlDarkSVG } from '@/assets/agent/html-dark.svg';
import { ReactComponent as HtmlLightSVG } from '@/assets/agent/html-light.svg';
import { ReactComponent as JavaDarkSVG } from '@/assets/agent/java-dark.svg';
import { ReactComponent as JavaLightSVG } from '@/assets/agent/java-light.svg';
import { ReactComponent as JsDarkSVG } from '@/assets/agent/js-dark.svg';
import { ReactComponent as JsLightSVG } from '@/assets/agent/js-light.svg';
import { ReactComponent as JsxDarkSVG } from '@/assets/agent/jsx-dark.svg';
import { ReactComponent as JsxLightSVG } from '@/assets/agent/jsx-light.svg';
import { ReactComponent as KotlinDarkSVG } from '@/assets/agent/kotlin-dark.svg';
import { ReactComponent as KotlinLightSVG } from '@/assets/agent/kotlin-light.svg';
import { ReactComponent as LessDarkSVG } from '@/assets/agent/less-dark.svg';
import { ReactComponent as LessLightSVG } from '@/assets/agent/less-light.svg';
import { ReactComponent as PhpDarkSVG } from '@/assets/agent/php-dark.svg';
import { ReactComponent as PhpLightSVG } from '@/assets/agent/php-light.svg';
import { ReactComponent as PythonDarkSVG } from '@/assets/agent/python-dark.svg';
import { ReactComponent as PythonLightSVG } from '@/assets/agent/python-light.svg';
import { ReactComponent as SassDarkSVG } from '@/assets/agent/sass-dark.svg';
import { ReactComponent as SassLightSVG } from '@/assets/agent/sass-light.svg';
import { ReactComponent as TsDarkSVG } from '@/assets/agent/ts-dark.svg';
import { ReactComponent as TsLightSVG } from '@/assets/agent/ts-light.svg';
import { ReactComponent as TsxDarkSVG } from '@/assets/agent/tsx-dark.svg';
import { ReactComponent as TsxLightSVG } from '@/assets/agent/tsx-light.svg';

export default (fileName: string, theme: string) => {
  const ext = fileName.split('.')?.pop()?.toLowerCase();

  switch (ext) {
    case 'ts':
      return theme === 'dark' ? <TsDarkSVG /> : <TsLightSVG />;
    case 'tsx':
      return theme === 'dark' ? <TsxDarkSVG /> : <TsxLightSVG />;
    case 'js':
      return theme === 'dark' ? <JsDarkSVG /> : <JsLightSVG />;
    case 'jsx':
      return theme === 'dark' ? <JsxDarkSVG /> : <JsxLightSVG />;
    case 'py':
      return theme === 'dark' ? <PythonDarkSVG /> : <PythonLightSVG />;
    case 'java':
      return theme === 'dark' ? <JavaDarkSVG /> : <JavaLightSVG />;
    case 'html':
    case 'htm':
      return theme === 'dark' ? <HtmlDarkSVG /> : <HtmlLightSVG />;
    case 'php':
      return theme === 'dark' ? <PhpDarkSVG /> : <PhpLightSVG />;
    case 'kt':
    case 'kts':
      return theme === 'dark' ? <KotlinDarkSVG /> : <KotlinLightSVG />;
    case 'css':
      return theme === 'dark' ? <CssDarkSVG /> : <CssLightSVG />;
    case 'less':
      return theme === 'dark' ? <LessDarkSVG /> : <LessLightSVG />;
    case 'sass':
    case 'scss':
      return theme === 'dark' ? <SassDarkSVG /> : <SassLightSVG />;
    default:
      return theme === 'dark' ? <CommonFileDarkSVG /> : <CommonFileLightSVG />;
  }
};
