import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import React, { ReactNode } from 'react';
import styles from './index.module.less';

interface BaseCardProps {
  filePath: string;
  statusIcon?: ReactNode;
  extraLeftContent?: ReactNode;
  rightContent?: ReactNode;
  children?: ReactNode;
  clickable?: boolean;
  onCardClick?: () => void;
}

const BaseCard: React.FC<BaseCardProps> = ({
  filePath,
  statusIcon,
  extraLeftContent,
  rightContent,
  children,
  clickable = true,
  onCardClick,
}) => {
  const handleFileClick = (uri: string) => {
    if (!uri || !clickable) return;

    if (onCardClick) {
      onCardClick();
      return;
    }

    jsBridgePostMessage({
      command: 'fileLinkage',
      data: { uri },
    });
  };

  if (!filePath) return null;

  return (
    <div className={styles.cardWrapper}>
      <div
        className={styles.cardHeader}
        onClick={() => handleFileClick(filePath)}
      >
        {statusIcon}
        <div className={styles.fileInfo}>
          <span className={styles.fileName} title={filePath}>
            {filePath?.split(/[/\\]/).pop()}
          </span>
          {extraLeftContent && (
            <span className={styles.extraInfo}>{extraLeftContent}</span>
          )}
        </div>
        {rightContent && (
          <div className={styles.rightContent}>{rightContent}</div>
        )}
      </div>
      {children && <div className={styles.childrenWrapper}>{children}</div>}
    </div>
  );
};

export default BaseCard;
