import logo from '@/assets/codelink/logo.png';
import AgentRender from '@/components/AgentRender';
import ErrorCard from '@/components/AgentRender/ErrorCard';
import UserInfo from '@/components/UserInfo';
import {
  ToolOutputEvent,
  ToolParameterFoundEvent,
  ToolType,
  ToolTypeErrorEvent,
  ToolUseDetectedEvent,
} from '@/interface/global';
import { FC, HTMLAttributes } from 'react';
import styles from './index.module.less';

interface ResponseCardProps extends HTMLAttributes<HTMLDivElement> {
  message: string;
  toolType?: ToolType;
  param?: ToolParameterFoundEvent;
  detect?: ToolUseDetectedEvent;
  output?: ToolOutputEvent;
  err?: ToolTypeErrorEvent;
  onAbort?: () => void;
  showAvatar?: boolean;
}

const responseName = 'CodeLink';

const ResponseCard: FC<ResponseCardProps> = (props) => {
  const { message, toolType, param, output, err, showAvatar = false } = props;
  /**
   * 如果解析出来的数据带有 message 属性，说明全局报错
   * event: {
       FrameworkEvent: FrameworkEvent;
       Error: {
         message: string;
       };
     };
   */
  const content = JSON.parse(message);

  return (
    message && (
      <div className={styles.responseCard}>
        {showAvatar && <UserInfo name={responseName} avatar={logo} />}
        {content?.message ? (
          <ErrorCard reason={content.message} />
        ) : (
          <AgentRender
            content={content}
            toolType={toolType}
            param={param}
            output={output}
            err={err}
          />
        )}
      </div>
    )
  );
};
export default ResponseCard;
