// useChatSession.ts
import { getExchangeId, getUiData } from '@/services/Api/agentic';
import { useAgenticStore, useGlobalStore } from '@/store';
import { useCallback } from 'react';

export const useChatSession = () => {
  const { chatId, setMsgMap, setEditFileList } = useAgenticStore();
  const {
    projectConfig: {
      sideCarIDEInfo: { sideCarPort },
    },
  } = useGlobalStore();

  /**
   * 获取交换ID
   */
  const fetchExchangeId = useCallback(
    async (sessionId: string) => {
      const { success, data } = await getExchangeId(
        { sessionId },
        `http://localhost:${sideCarPort}`,
      );
      // @ts-ignore
      return success ? data.exchange_id.split('_')[1] : null;
    },
    [sideCarPort],
  );

  /**
   * 获取历史聊天记录
   */
  const fetchHistory = useCallback(
    async (sessionId: string) => {
      const { success, data } = await getUiData(
        { sessionId },
        `http://localhost:${sideCarPort}`,
      );
      if (success) {
        setMsgMap(data.uiData);
        setEditFileList(data.editFileList);
      }
    },
    [setMsgMap, setEditFileList, sideCarPort],
  );

  return {
    chatId,
    fetchExchangeId,
    fetchHistory,
  };
};
