import {
  ToolOutputResponseEvent,
  ToolParameterInput,
  ToolType,
} from '@/interface/global';
import { useGlobalStore } from '@/store';
import AcceptedCard from './AcceptedCard';
import PendingCard from './PendingCard';
import RejectedCard from './RejectedCard';
import { useTerminalCommand } from './useTerminalCommand';

interface TerminalCommandProps {
  param?: ToolParameterInput;
  output?: ToolOutputResponseEvent;
  err?: string;
  toolType?: ToolType;
}

const TerminalCommand: React.FC<TerminalCommandProps> = ({ param, output }) => {
  const {
    pluginConfig: { theme },
  } = useGlobalStore();
  const { status, command, handleCopy, handleAccept, handleReject } =
    useTerminalCommand(output, param);

  if (output && status === 'accepted')
    return <AcceptedCard command={command} theme={theme} />;
  if (status === 'rejected')
    return <RejectedCard command={command} theme={theme} />;
  if (param?.field_name === 'command') {
    return (
      <PendingCard
        command={command}
        commandId={param.optional_field || ''}
        status={status}
        theme={theme}
        onCopy={handleCopy}
        onAccept={handleAccept}
        onReject={handleReject}
      />
    );
  }
  return null;
};

export default TerminalCommand;
