import { ReactComponent as FileSVG } from '@/assets/common/file.svg';
import { ReactComponent as MCPSVG } from '@/assets/footer/mcp.svg';
import { ReactComponent as NotepadsSVG } from '@/assets/footer/notepad.svg';
// import { ReactComponent as PastChatsSVG } from '@/assets/pastChat.svg';
import { ReactComponent as RulesSVG } from '@/assets/footer/ruler.svg';
import { jsBridgePostMessageWithCallback } from '@/services/JsBridge/jsBridgePostMessage';
import useRegisterMessage from '@/services/JsBridge/useRegisterMessage';
import { useGlobalStore } from '@/store';
import { Spin } from 'antd';
import classNames from 'classnames';
import React, {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import { v4 as uuid } from 'uuid';
import Files from './components/Files';
import McpTool from './components/McpTool';
import Notepads from './components/Notepads';
// import Pastchats from './components/Pastchats';
import Rules from './components/Rules';
import {
  FILES,
  FOLDERS,
  MCP_TOOLS,
  NOTE_PADS,
  PanelType,
  PAST_CHATS,
  RULES,
} from './constants';
import styles from './index.module.less';
import { getSearchTerm, useDebounce } from './utils';

interface ExpandPanelProps {
  onAbort: (str: string, close?: boolean, data?: any) => void; // 明确 3 个参数
  onClose: () => void;
  showSwitch: boolean;
  position: number;
  filterValue: string;
  inputAreaRef: any;
}
interface RefMethods {
  pick: () => void;
  up: () => void;
  down: () => void;
}
type ActionMap<T extends keyof RefMethods> = {
  [K in Exclude<PanelType, typeof PAST_CHATS>]: () => ReturnType<
    RefMethods[T]
  > | void; // 允许返回 void
};

const ExpandPanel: React.FC<ExpandPanelProps> = forwardRef((props, ref) => {
  const { onAbort, onClose, showSwitch, position, filterValue, inputAreaRef } =
    props;
  const {
    pluginConfig: { theme, emailPrefix: userAccount, ide: myIDE },
    projectConfig: { sideCarIDEInfo },
  } = useGlobalStore();
  const iconColor = theme === 'dark' ? '#9da3ae' : '#000';
  const textColor = theme === 'dark' ? '#ccc' : '#000';
  const keyMapIcons = [
    // <FolderOutlined style={{ fontSize: '16px', color: iconColor }} />,
    <FileSVG key="files" />,
    <NotepadsSVG key="notepads" width="16" height="16" />,
    <MCPSVG key="mcp" />,
    <RulesSVG key="rules" width="16" height="16" />,
  ];

  const [panelLoadingSwitch, setPanelLoadingSwitch] = useState(false);
  const [selectedLine, setSelectedLine] = useState<number>(0);
  const [myContent, setMyContent] = useState<string>('');
  const [newRuleList, setNewRuleList] = useState([]); // 特定规则列表
  // const [pastChatsList, setPastChatsList] = useState<HistorySummaryListItem[]>(
  //   [],
  // ); // 历史对话列表
  const [newFolderList, setNewFolderList] = useState([]); // 文件夹列表
  const [newNotePadList, setNewNotePadList] = useState([]); // 记事本列表
  const [newFileList, setNewFileList] = useState([]); // 文件列表
  const [newMcpList, setNewMcpList] = useState([]); // MCP列表
  const scrollBarRef = useRef<HTMLDivElement>(null); // 滚动区域节点
  const filesRef = useRef<RefMethods>(null);
  // const foldersRef = useRef<RefMethods>(null);
  // const pastchatsRef = useRef<RefMethods>(null);
  const notePadsRef = useRef<RefMethods>(null);
  const rulesRef = useRef<RefMethods>(null);
  const baseKeyMap = useMemo(() => [FILES, NOTE_PADS, MCP_TOOLS, RULES], []);
  const [keyMap, setKeyMap] = useState(baseKeyMap);
  const firstPickRef = useRef(0);

  const fetchFiles = async (searchStr = '') => {
    if (searchStr && myContent) {
      setPanelLoadingSwitch(true);
      const res = await jsBridgePostMessageWithCallback({
        command: 'searchFileList',
        data: {
          uuid: uuid(),
          userInput: searchStr,
        },
      });
      if (myIDE === 'vscode') {
        setPanelLoadingSwitch(false);
        setNewFileList(res.data);
      }
    } else {
      jsBridgePostMessageWithCallback({
        command: 'getDefaultFileList',
        data: {},
      }).then((res) => {
        if (res && res.data) {
          setNewFileList(res.data);
        }
      });
    }
  };

  const fetchRules = async () => {
    const res2 = await jsBridgePostMessageWithCallback({
      command: 'manualRuleListReq',
      data: {},
    });
    if (res2?.data) {
      setNewRuleList(res2.data);
    }
  };

  const fetchNotePad = async () => {
    const res = await jsBridgePostMessageWithCallback({
      command: 'notepadFileList',
      data: { userAccount },
    });
    if (res && res.data) {
      setNewNotePadList(res.data);
    }
  };

  const fetchMCPList = async () => {
    const res = await jsBridgePostMessageWithCallback({
      command: 'mcpDetailList',
      data: {},
    });
    if (res?.data) {
      setNewMcpList(res.data);
    }
  };

  // const fetchFolder = (searchStr = '') => {
  //   let res = null;
  //   if (searchStr && myContent) {
  //     setPanelLoadingSwitch(true);
  //     jsBridgePostMessageWithCallback({
  //       command: 'searchDirectory',
  //       data: {
  //         uuid: uuid(),
  //         userInput: searchStr,
  //       },
  //     }).then((res) => {
  //       setPanelLoadingSwitch(false);
  //       if (myIDE === 'jetbrains') {
  //         if (res?.data?.fileTreeNodes) {
  //           const developers: any = deepFindAll(
  //             res.data.fileTreeNodes,
  //             (folder) => folder.name.indexOf(searchStr) > -1,
  //           );
  //           setNewFolderList(developers);
  //         }
  //       } else {
  //         if (res?.data) {
  //           const developers: any = deepFindAll(
  //             res.data,
  //             (folder) => folder.name.indexOf(searchStr) > -1,
  //           );
  //           setNewFolderList(developers);
  //         }
  //       }
  //     });
  //   } else {
  //     jsBridgePostMessageWithCallback({
  //       command: 'defaultDirectoryList',
  //       data: {},
  //     }).then((res) => {
  //       if (res?.data) setNewFolderList(flattenTree(res.data));
  //     });
  //   }
  // };

  // const fetchHistorySummaryList = async () => {
  //   const { success, data: res } = await getAgenticHistorySummaryList({
  //     repoRef: sideCarIDEInfo?.rootDirectory
  //       ? `local/${sideCarIDEInfo.rootDirectory}`
  //       : '',
  //   });
  //   if (success && Array.isArray(res)) {
  //     setPastChatsList(res);
  //   } else setPastChatsList([]);
  // };

  const onParentPick = (info: any = {}) => {
    onAbort(info.text, true, info);
  };

  function createActionMap<T extends keyof RefMethods>(
    methodName: T,
  ): ActionMap<T> {
    return {
      [FILES]: () => filesRef.current?.[methodName](),
      // [FOLDERS]: () => foldersRef.current?.[methodName](),
      // [PAST_CHATS]: () => pastchatsRef.current?.[methodName](),
      [NOTE_PADS]: () => notePadsRef.current?.[methodName](),
      [RULES]: () => rulesRef.current?.[methodName](),
    };
  }

  const pickActions = createActionMap('pick');
  const downActions = createActionMap('down');
  const upActions = createActionMap('up');

  const pick = () => {
    if (!myContent) {
      let gongn = keyMap[selectedLine];
      setMyContent(gongn);
      firstPickRef.current = 1;
      if (gongn === MCP_TOOLS) {
        onAbort('');
        return;
      }
      setSelectedLine(0);
      onAbort(gongn);
    } else {
      // 点击二级菜单 输出内容 并清空选中项
      if (
        myContent !== PAST_CHATS &&
        pickActions[myContent as Exclude<PanelType, typeof PAST_CHATS>]
      ) {
        pickActions[myContent as Exclude<PanelType, typeof PAST_CHATS>]();
      }
      setMyContent('');
      setSelectedLine(0);
    }
  };

  const down = () => {
    if (!myContent) {
      setSelectedLine((prev) => (prev >= 3 ? 0 : prev + 1));
    } else if (
      myContent !== PAST_CHATS &&
      downActions[myContent as Exclude<PanelType, typeof PAST_CHATS>]
    ) {
      downActions[myContent as Exclude<PanelType, typeof PAST_CHATS>]();
    }
  };

  const up = () => {
    if (!myContent) {
      setSelectedLine((prev) => (prev <= 0 ? 3 : prev - 1));
    } else if (
      myContent !== PAST_CHATS &&
      upActions[myContent as Exclude<PanelType, typeof PAST_CHATS>]
    ) {
      upActions[myContent as Exclude<PanelType, typeof PAST_CHATS>]();
    }
  };

  useImperativeHandle(ref, () => ({
    pick: pick,
    down: down,
    up: up,
  }));

  const searchTerm = useMemo(
    () => getSearchTerm(filterValue, myContent),
    [filterValue, myContent],
  );

  const onRefresh = useCallback((msg: any) => {
    if (msg) {
      fetchMCPList();
    }
  }, []);

  useRegisterMessage('mcpWebviewRefresh', onRefresh);

  const debouncedSearchTerm = useDebounce(searchTerm, 500);

  const onReceiveSearchData = useCallback(
    (data: any) => {
      if (myIDE === 'jetbrains') {
        setPanelLoadingSwitch(false);
        if (data?.fileContentDTOList) {
          setNewFileList(data.fileContentDTOList);
        }
      }
    },
    [filterValue],
  );

  useRegisterMessage('searchFileListResp', onReceiveSearchData);

  useEffect(() => {
    const timer = setTimeout(async () => {
      if (!myContent) {
        if (searchTerm.length <= 1) {
          setKeyMap(baseKeyMap);
          return;
        }
        if (searchTerm.length > 3) {
          let pureValue = searchTerm.replace(/^@|:/g, '');
          let newMap = [...baseKeyMap].filter((item) =>
            item.toLowerCase().includes(pureValue.toLowerCase()),
          );
          setSelectedLine(0);
          setKeyMap(newMap);
        }
      } else {
        if (searchTerm.length > 0 && searchTerm.length < 3) return;
        if (firstPickRef.current !== 1) {
          if (myContent === FOLDERS) {
            // fetchFolder(searchTerm)
          } else if (myContent === FILES) {
            fetchFiles(searchTerm);
          }
        }
        firstPickRef.current++;
      }
    }, 500);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const isInsideModal =
        scrollBarRef.current &&
        scrollBarRef.current.contains(event.target as Node); // 检查点击是否在弹窗内部
      const isInsideExcluded =
        inputAreaRef.current && inputAreaRef.current.contains(event.target); // 检查点击是否在排除区域内部
      if (!isInsideModal && !isInsideExcluded) {
        // 如果既不在弹窗内，也不在排除区域内，则关闭弹窗
        onClose();
      }
    };
    const getMatch = () => {
      const regex = /@([^:]+):/;
      const match = filterValue.match(regex);
      return match;
    };

    setSelectedLine(0);
    if (showSwitch) {
      if (!myContent) {
        const fetchFunctions = [
          // fetchHistorySummaryList,
          // fetchFolder,
          fetchNotePad,
          fetchRules,
          fetchFiles,
          fetchMCPList,
        ];
        let currentIndex = 0;
        const intervalId = setInterval(() => {
          if (currentIndex < fetchFunctions.length) {
            fetchFunctions[currentIndex]();
            currentIndex++;
          } else {
            clearInterval(intervalId);
          }
        }, 10);
      }

      // 在打开面板时 匹配输入框内容  如果匹配到二级面板 则直接展示二级面板
      const match = getMatch();
      if (match) {
        let newMap = [...baseKeyMap].filter((item) =>
          item.toLowerCase().includes(match[1].toLowerCase()),
        );
        if (newMap.length) {
          setMyContent(newMap[0]);
        }
      } else {
        setMyContent('');
      }

      document.addEventListener('mousedown', handleClickOutside);
    } else {
      const match = getMatch();
      if (!match) {
        setMyContent('');
      }
      setKeyMap(baseKeyMap);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showSwitch]);

  return (
    <div
      style={{
        display: showSwitch ? 'block' : 'none',
        bottom: `${position + 9}px`,
        borderColor: theme === 'dark' ? `#394250` : '#ddd',
      }}
      ref={scrollBarRef}
      className={classNames(
        styles.expandPanelContent,
        theme === 'dark'
          ? styles.expandPanelContentDark
          : styles.expandPanelContentLight,
      )}
    >
      <div
        style={{
          display: !myContent ? 'block' : 'none',
        }}
      >
        {keyMap.map((item, index) => {
          return (
            <div
              key={index}
              className={classNames(
                styles.expandCell,
                selectedLine === index ? styles.active : '',
              )}
              onMouseEnter={() => {
                setSelectedLine(index);
              }}
              onClick={() => {
                pick();
              }}
            >
              <div className={styles.left} style={{ color: iconColor }}>
                {keyMapIcons[index]}
              </div>
              <div className={styles.right}>
                <span className={styles.name} style={{ color: textColor }}>
                  {item === 'MCPTools' ? 'MCP Tools' : item}
                </span>
              </div>
            </div>
          );
        })}
      </div>
      <Spin spinning={panelLoadingSwitch}>
        {/* <Folders ref={foldersRef} theme={theme} show={myContent === FOLDERS} list={newFolderList} inputValue={debouncedSearchTerm} onParentPick={onParentPick} /> */}
        <Files
          ref={filesRef}
          theme={theme}
          show={myContent === FILES}
          list={newFileList}
          inputValue={debouncedSearchTerm}
          onParentPick={onParentPick}
        />
        <McpTool
          list={newMcpList}
          theme={theme}
          show={myContent === MCP_TOOLS}
        />
        <Notepads
          ref={notePadsRef}
          theme={theme}
          show={myContent === NOTE_PADS}
          list={newNotePadList}
          inputValue={debouncedSearchTerm}
          onParentPick={onParentPick}
        />
        {/* <Pastchats
          ref={pastchatsRef}
          theme={theme}
          show={myContent === PAST_CHATS}
          list={pastChatsList}
          inputValue={debouncedSearchTerm}
          onParentPick={onParentPick}
          onDeleteSuccess={fetchHistorySummaryList}
        /> */}
        <Rules
          ref={rulesRef}
          theme={theme}
          show={myContent === RULES}
          list={newRuleList}
          inputValue={debouncedSearchTerm}
          onParentPick={onParentPick}
        />
      </Spin>
    </div>
  );
});
export default ExpandPanel;
