// useAgentEvents.ts
import { useUnifiedNewChat } from '@/hooks/useUnifiedNewChat';
import { useEffect } from 'react';
import emitter from '../eventBus';

export const useAgentEvents = () => {
  const { createUnifiedNewChat } = useUnifiedNewChat();

  useEffect(() => {
    const handleClear = () => {
      // 只中断请求，不立即清空数据
      emitter.emit('abortRequest');
      // 发出一个新的事件，表示历史记录上传完毕可以清空数据了
      setTimeout(() => emitter.emit('clearAfterUpload'), 200);
    };

    const handleClearAfterUpload = () => {
      // 使用统一的创建新会话方法，它会处理所有数据的清空
      createUnifiedNewChat();
    };

    emitter.on('clear', handleClear);
    emitter.on('clearAfterUpload', handleClearAfterUpload);

    return () => {
      emitter.off('clear', handleClear);
      emitter.off('clearAfterUpload', handleClearAfterUpload);
    };
  }, [createUnifiedNewChat]);
};
