import { DiffMsgObj } from '@/services/Api/agentic';
import { useAgenticStore } from '@/store';
import parseGitDiff from '@/utils/parseGitDiff';
import { useCallback } from 'react';

export const useUpdateEditFileList = () => {
  const { editFileList, setEditFileList } = useAgenticStore();

  const updateEditFileList = useCallback(
    (data: { delete?: string[]; modify?: DiffMsgObj[] }) => {
      if (!data) return;

      if (data.delete && data.delete.length > 0) {
        const newList = editFileList.filter(
          (file) => !data.delete!.includes(file.fileName),
        );
        setEditFileList(newList);
      }

      if (data.modify && data.modify.length > 0) {
        const newList = [...editFileList];
        data.modify.forEach((modifiedFile: DiffMsgObj) => {
          const { file_path, new_content, session_diff, session_old_content } =
            modifiedFile;
          const { addedLines, removedLines } = parseGitDiff(session_diff);
          const existingIndex = newList.findIndex(
            (file) => file.fileName === file_path,
          );
          if (existingIndex !== -1) {
            newList[existingIndex] = {
              fileName: file_path,
              addLine: addedLines,
              deleteLine: removedLines,
              oldContent: session_old_content,
              newContent: new_content,
              state: newList[existingIndex].state,
            };
          } else {
            newList.push({
              fileName: file_path,
              addLine: addedLines,
              deleteLine: removedLines,
              oldContent: session_old_content,
              newContent: new_content,
              state: null,
            });
          }
        });
        setEditFileList(newList);
      }
    },
    [editFileList, setEditFileList],
  );

  return updateEditFileList;
};
