import { ReactComponent as DefaultUserSVG } from '@/assets/user/icon-user.svg';
import { renderSelectedCodeCard } from '@/pages/Agentic/SelectedCodeList';
import { AgentMsgItem } from '@/pages/Agentic/type';
import { agentRedo, agentRestore } from '@/services/Api/agentic';
import { useAgenticStore, useGlobalStore } from '@/store';
import { Avatar, Button, Modal, Space, message } from 'antd';
import classNames from 'classnames';
import { debounce } from 'lodash';
import { FC } from 'react';
import { useUpdateEditFileList } from './hooks/useUpdateEditFileList';
import styles from './index.module.less';

interface ReqCardProps extends AgentMsgItem {
  onSelect?: (messageId: string) => void;
  isSelected?: boolean;
  isLastMessage?: boolean;
  isLatestUserMessage?: boolean;
}

const RequestCard: FC<ReqCardProps> = (props) => {
  const {
    content,
    contexts,
    messageId,
    onSelect,
    isLatestUserMessage,
    exchangeId,
  } = props;
  const { chatId, loading, buttonStateMap, setButtonState } = useAgenticStore();
  const {
    pluginConfig: { avatar = <DefaultUserSVG /> },
  } = useGlobalStore();
  const { selectedCodeList = [] } = contexts ?? {};
  const {
    pluginConfig: { theme },
    projectConfig: { sideCarIDEInfo },
  } = useGlobalStore();
  const updateEditFileList = useUpdateEditFileList();

  const buttonState = buttonStateMap[messageId] || 'restore';

  const handleSelect = debounce(async (messageId: string) => {
    const { sideCarPort, projectId, editorUrl } = sideCarIDEInfo;

    if (buttonState === 'restore') {
      Modal.confirm({
        title: '确认恢复',
        content: '确定要恢复到该检查点吗？这将清除该检查点之后的所有消息。',
        okText: '确认',
        cancelText: '取消',
        onOk: async () => {
          // 1. 调用撤销接口
          const { success, data } = await agentRestore(
            {
              session_id: chatId,
              exchange_id: `request_${exchangeId}`,
              project_id: projectId,
              edit_url: editorUrl,
            },
            `http://localhost:${sideCarPort}`,
          );
          if (success) {
            onSelect?.(messageId);
            setButtonState(messageId, 'redo');
            updateEditFileList(data);
          } else {
            message.error('restore error');
          }
        },
      });
    } else {
      const { success, data } = await agentRedo(
        {
          session_id: chatId,
          exchange_id: `request_${exchangeId}`,
          project_id: projectId,
          edit_url: editorUrl,
        },
        `http://localhost:${sideCarPort}`,
      );
      if (success) {
        onSelect?.(messageId);
        setButtonState(messageId, 'restore');
        updateEditFileList(data);
      } else {
        message.error('redo error');
      }
    }
  }, 300);

  return (
    <div
      className={classNames(styles.requestCard, {
        [styles.latestMessage]: isLatestUserMessage,
        [styles[theme]]: isLatestUserMessage,
      })}
    >
      <div className={styles.userInfo}>
        <Space align="start">
          <Avatar src={avatar} className={styles.avatar} size={30} />
        </Space>
        <div className={styles.content}>
          {selectedCodeList?.length > 0 && (
            <div className={styles.codeCardsContainer}>
              {selectedCodeList.map((item) =>
                renderSelectedCodeCard(item, { theme }),
              )}
            </div>
          )}
          {content}
          {!loading && (
            <div className={styles.btnContainer}>
              <Button
                type="link"
                size="small"
                onClick={() => handleSelect(messageId)}
                className={styles.selectButton}
              >
                {buttonState === 'restore'
                  ? 'Restore checkoutpoint'
                  : 'Redo checkoutpoint'}
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
export default RequestCard;
