import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useAgenticStore, useGlobalStore } from '@/store';
import getFileIcon from '@/utils/getFileIcon';
import { CheckOutlined, CloseOutlined } from '@ant-design/icons';
import { Tooltip } from 'antd';
import classNames from 'classnames';
import { EditFileItem } from '.';
import styles from './index.module.less';

interface ListItemProps {
  item: EditFileItem;
}

const ListItem: React.FC<ListItemProps> = ({ item }) => {
  const {
    pluginConfig: { theme },
  } = useGlobalStore();
  const { editFileList, setEditFileList } = useAgenticStore();

  const handleOpenDiff = (item: EditFileItem) => {
    jsBridgePostMessage({
      command: 'agenticDiffFile',
      data: {
        oldContent: item.state === 'accept' ? item.newContent : item.oldContent,
        newContent: item.newContent,
        filePath: item.fileName,
      },
    });
  };

  const handleAccept = (fileName: string, oldContent: string) => {
    const updatedList: Array<EditFileItem> = editFileList.map((item) =>
      item.fileName === fileName ? { ...item, state: 'accept' } : item,
    );
    setEditFileList(updatedList);
    jsBridgePostMessage({
      command: 'accept',
      data: {
        fileName: [fileName],
        oldContent: [oldContent],
      },
    });
  };

  const handleReject = (fileName: string, oldContent: string) => {
    const updatedList: Array<EditFileItem> = editFileList.map((item) =>
      item.fileName === fileName ? { ...item, state: 'reject' } : item,
    );
    setEditFileList(updatedList);
    jsBridgePostMessage({
      command: 'reject',
      data: {
        fileName: [fileName],
        oldContent: [oldContent],
      },
    });
  };

  return (
    <div
      key={item.fileName}
      className={styles.fileItem}
      onClick={() => handleOpenDiff(item)}
    >
      <span className={styles.fileIcon}>
        {getFileIcon(item.fileName, theme)}
      </span>
      <div className={styles.fileName}>
        <div className={styles.nameWrapper}>
          <Tooltip title={item.fileName}>
            <span>{item.fileName?.split(/[/\\]/).pop()}</span>
          </Tooltip>
          <span className={styles.addition}>+{item.addLine}</span>
          <span className={styles.deletion}>-{item.deleteLine}</span>
          <div className={styles.statusWrapper}>
            <Tooltip title="已接受">
              {item.state === 'accept' && (
                <span className={styles.accept}></span>
              )}
            </Tooltip>
            <Tooltip title="已拒绝">
              {item.state === 'reject' && (
                <span className={styles.reject}>x</span>
              )}
            </Tooltip>
          </div>
        </div>
      </div>
      <div className={styles.fileActions}>
        {item.state === null && (
          <Tooltip title="拒绝修改">
            <CloseOutlined
              className={classNames(styles.actionIcon, styles.red)}
              onClick={(e) => {
                e.stopPropagation();
                handleReject(item.fileName, item.oldContent);
              }}
            />
          </Tooltip>
        )}
        {item.state === null && (
          <Tooltip title="接受修改">
            <CheckOutlined
              className={classNames(styles.actionIcon, styles.green)}
              onClick={(e) => {
                e.stopPropagation();
                handleAccept(item.fileName, item.oldContent);
              }}
            />
          </Tooltip>
        )}
      </div>
    </div>
  );
};
export default ListItem;
