// useAgentUrlParams.ts
import { useUnifiedNewChat } from '@/hooks/useUnifiedNewChat';
import { useGlobalStore } from '@/store';
import { history, useLocation } from '@umijs/max';
import { useEffect, useRef } from 'react';

export const useAgentUrlParams = (
  chatId: string,
  setChatId: (id: string) => void,
  fetchHistory: (sessionId: string) => Promise<void>,
) => {
  const {
    projectConfig: { sideCarIDEInfo },
  } = useGlobalStore();
  const location = useLocation();
  const hasInitialized = useRef<boolean>(false);
  const { createUnifiedNewChat } = useUnifiedNewChat();

  useEffect(() => {
    // sideCar 启动成功才可以调用
    if (sideCarIDEInfo && !hasInitialized.current) {
      hasInitialized.current = true;

      const searchParams = new URLSearchParams(location.search);
      const id = searchParams.get('chatId');

      if (id) {
        // 如果 URL 中有 chatId 参数，说明是从历史记录跳转过来的
        setChatId(id);
        fetchHistory(id);
      } else if (!chatId) {
        // 如果没有 chatId 且 URL 中也没有参数，创建新会话
        createUnifiedNewChat().then((sessionId) => {
          if (sessionId) {
            // 创建成功后更新 URL
            history.push(`/chat?chatId=${sessionId}`);
          }
        });
      }
    }
  }, [
    sideCarIDEInfo,
    chatId,
    setChatId,
    fetchHistory,
    location.search,
    createUnifiedNewChat,
  ]);
};
