import { FrameworkEvent, ToolInputPartial } from '@/interface/global';

/**
 * 由于 sideCar 过滤指令成本过高，因此在前端进行过滤
 */

export const arr: Array<string> = [
  'fs_file_path',
  'directory_path',
  'instruction',
  'command',
  'instruction',
  'result',
  'question',
  'codelink_workspace',
];

export const hasRequiredProperties = (obj: ToolInputPartial) => {
  if (!obj) return false;
  return 'AttemptCompletion' in obj || 'AskFollowupQuestions' in obj;
  // return (
  //   ('AttemptCompletion' in obj && !obj.AttemptCompletion.command) ||
  //   'AskFollowupQuestions' in obj
  // );
};

export const shouldSkip = (frameworkEvent: FrameworkEvent) => {
  if (
    (frameworkEvent.ToolParameterFound?.tool_parameter_input &&
      !arr.includes(
        frameworkEvent.ToolParameterFound.tool_parameter_input?.field_name,
      )) ||
    (frameworkEvent.ToolParameterFound &&
      frameworkEvent.ToolParameterFound.tool_parameter_input.field_name ===
        'instruction')
  ) {
    return true;
  }

  return false;
};
