import {
  FrameworkEvent,
  ToolOutputEvent,
  ToolParameterFoundEvent,
  ToolType,
  ToolTypeErrorEvent,
} from '@/interface/global';
import { FC, memo, useCallback } from 'react';

import EditFile from './EditFile';
import Markdown from './Markdown';
import ParseFile from './ParseFile';
import SearchFileWithRes from './SearchFileWithRes';
import TerminalCommand from './TerminalCard';

export enum ToolTypeEnum {
  LIST_FILES = 'ListFiles',
  SEARCH_FILE_CONTENT_WITH_REGEX = 'SearchFileContentWithRegex',
  OPEN_FILE = 'OpenFile',
  CODE_EDITING = 'CodeEditing',
  LSP_DIAGNOSTICS = 'LSPDiagnostics',
  ASK_FOLLOWUP_QUESTIONS = 'AskFollowupQuestions',
  ATTEMPT_COMPLETION = 'AttemptCompletion',
  REPO_MAP_GENERATION = 'RepoMapGeneration',
  TERMINAL_COMMAND = 'TerminalCommand',
}

const componentMap = {
  [ToolTypeEnum.LIST_FILES]: SearchFileWithRes,
  [ToolTypeEnum.SEARCH_FILE_CONTENT_WITH_REGEX]: SearchFileWithRes,
  [ToolTypeEnum.REPO_MAP_GENERATION]: SearchFileWithRes,
  [ToolTypeEnum.OPEN_FILE]: ParseFile,
  [ToolTypeEnum.TERMINAL_COMMAND]: TerminalCommand,
  [ToolTypeEnum.CODE_EDITING]: EditFile,
  [ToolTypeEnum.LSP_DIAGNOSTICS]: Markdown,
  [ToolTypeEnum.ASK_FOLLOWUP_QUESTIONS]: Markdown,
  [ToolTypeEnum.ATTEMPT_COMPLETION]: Markdown,
};

interface AgentRenderProps {
  content: FrameworkEvent;
  toolType?: ToolType;
  param?: ToolParameterFoundEvent;
  output?: ToolOutputEvent;
  err?: ToolTypeErrorEvent;
}

const AgentRender: FC<AgentRenderProps> = ({
  content,
  toolType,
  param,
  output,
  err,
}) => {
  const renderComponent = useCallback(() => {
    if (toolType) {
      const Component = componentMap[toolType];
      if (!Component) return null;
      if (Component === Markdown) {
        return (
          <Markdown
            message={param?.tool_parameter_input?.field_content_up_until_now}
          />
        );
      }
      return (
        <Component
          param={param?.tool_parameter_input}
          output={output?.ToolOutputResponse}
          err={err?.error_string}
          toolType={toolType}
        />
      );
    }
    return null;
  }, [toolType, param, output, err]);

  return content.ToolThinking?.thinking ? (
    <Markdown message={content.ToolThinking?.thinking} />
  ) : (
    renderComponent()
  );
};

export default memo(AgentRender);
