import { ReactComponent as WaitSVG } from '@/assets/agent/wait.svg';
import { Button } from 'antd';
import React from 'react';
import styles from './index.module.less';

interface PendingCardProps {
  command: string;
  commandId: string;
  status: 'pending' | 'accepted' | 'rejected';
  theme?: 'dark' | 'light';
  onCopy: (text: string) => void;
  onAccept: (command: string, commandId: string) => void;
  onReject: (commandId: string) => void;
}

const PendingCard: React.FC<PendingCardProps> = ({
  command,
  commandId,
  status,
  theme,
  onAccept,
  onReject,
}) => {
  return (
    <div className={styles.terminalCard}>
      <div className={styles.title}>
        <WaitSVG />
        执行下方终端命令
      </div>
      <div
        className={`${styles.content} ${
          theme === 'dark' ? styles.borderDark : styles.borderLight
        }`}
      >
        {command}
      </div>
      <div className={styles.buttonGroup}>
        <Button
          className={
            styles.linkBtn +
            ' ' +
            (status === 'accepted' ? styles.accepted : '')
          }
          disabled={status !== 'pending'}
          onClick={() => onAccept(command, commandId)}
        >
          {status === 'accepted' ? '已接受' : '接受'}
        </Button>
        <Button
          className={
            styles.linkBtn +
            ' ' +
            (status === 'rejected' ? styles.rejected : '')
          }
          disabled={status !== 'pending'}
          onClick={() => onReject(commandId)}
        >
          {status === 'rejected' ? '已拒绝' : '拒绝'}
        </Button>
      </div>
    </div>
  );
};

export default PendingCard;
