import { AgentStreamMessage } from '@/interface/global';
import { FetchSSE } from '@/services/Api/requestInstance';
import { v4 as uuid } from 'uuid';
import { SendAgentChatParams, SendAgentChatResponse } from './type';
import { hasRequiredProperties, shouldSkip } from './utils';

export async function sendAgentChat(
  params: SendAgentChatParams,
): Promise<SendAgentChatResponse> {
  const {
    chatId,
    sideCarPort,
    emailPrefix,
    payload,
    onReceiveAgentMessage,
    onLoadingStatusChange,
    onFinish,
    onError,
    onFinally,
    abortRef,
  } = params;
  onLoadingStatusChange?.(true);
  let fetchInstanceRef: FetchSSE | null = null;

  const messageId = uuid();
  const data = {
    chatId,
    messageId,
    ...payload,
  };

  const onAgentMessage = (message: AgentStreamMessage) => {
    if (message?.event?.Error) {
      onLoadingStatusChange?.(false);
      onError?.({
        error: JSON.stringify(message?.event?.Error),
        messageId,
      });
    } else {
      if (message?.event?.FrameworkEvent) {
        const frameworkEvent = message.event.FrameworkEvent;
        if (shouldSkip(frameworkEvent)) return;

        if (
          hasRequiredProperties(
            frameworkEvent?.ToolUseDetected?.tool_use_partial_input,
          )
        ) {
          // 主动中断连接
          if (fetchInstanceRef) {
            setTimeout(() => {
              fetchInstanceRef?.abort();
              onLoadingStatusChange?.(false);

              onFinish?.({
                finishReason: 'completed_by_condition',
                messageId,
              });
            }, 1000);
          }
          return;
        }

        onReceiveAgentMessage?.({
          content: JSON.stringify(message?.event?.FrameworkEvent),
          messageId: uuid(),
          exchangeId: message?.exchange_id,
          renderId: message?.event.FrameworkEvent?.ToolThinking
            ? 'think' + chatId + message?.exchange_id
            : 'state' + chatId + message?.exchange_id,
          toolType:
            message?.event?.FrameworkEvent?.ToolTypeFound?.tool_type || '',
          param: message?.event?.FrameworkEvent?.ToolParameterFound || '',
          detect: message?.event?.FrameworkEvent?.ToolUseDetected || '',
          output: message?.event?.FrameworkEvent?.ToolOutput || '',
          err: message?.event?.FrameworkEvent?.ToolCallError || '',
          agentErr: message?.event?.FrameworkEvent?.AgenticError || '',
        });
      }
    }
  };

  const fetchInstance = new FetchSSE({
    type: 'agent',
    url: '/api/agentic/agent_tool_use',
    headers: {
      'email-prefix': emailPrefix,
    },
    sideCarPort,
    onAgentMessage,
    onError: (e) => {
      onLoadingStatusChange?.(false);
    },
    onFinish: (finishReason: string) => {
      onLoadingStatusChange?.(false);
      onFinish?.({ finishReason, messageId });
    },
    onFinally,
    data,
  });

  // 将创建的实例赋值给 fetchInstanceRef
  fetchInstanceRef = fetchInstance;

  if (abortRef) {
    const originalAbort = fetchInstance.abort.bind(fetchInstance);
    abortRef.current = () => {
      originalAbort();
      onLoadingStatusChange?.(false); // 中止请求时取消加载状态
    };
  }

  return {
    abort: () => {
      fetchInstance.abort();
      onLoadingStatusChange?.(false); // 中止请求时取消加载状态
    },
  };
}
