import {
  ToolOutputResponseEvent,
  ToolParameterInput,
} from '@/interface/global';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import copyToClipboard from '@/utils/copyToClipboard';
import { message } from 'antd';
import { useMemo, useState } from 'react';

export const useTerminalCommand = (
  output?: ToolOutputResponseEvent,
  param?: ToolParameterInput,
) => {
  const [status, setStatus] = useState<'pending' | 'accepted' | 'rejected'>(
    'pending',
  );

  const command = useMemo(
    () => output?.delta || param?.field_content_delta || '',
    [output?.delta, param?.field_content_delta],
  );

  const handleCopy = (text: string) => copyToClipboard(text, '复制成功');

  const handleAccept = (command: string, commandId: string) => {
    if (!commandId) return message.error('commandId 不存在');
    setStatus('accepted');
    jsBridgePostMessage({
      command: 'executeCommand',
      data: { commandId, command, inTerminal: false },
    });
  };

  const handleReject = (commandId: string) => {
    if (!commandId) return message.error('commandId 不存在');
    setStatus('rejected');
    jsBridgePostMessage({ command: 'cancelCommand', data: { commandId } });
  };

  return {
    status,
    setStatus,
    command,
    handleCopy,
    handleAccept,
    handleReject,
  };
};
