import { ReactComponent as AlertSVG } from '@/assets/common/alert.svg';
import { ReactComponent as SuccessSVG } from '@/assets/common/file_success.svg';
import {
  ToolOutputResponseEvent,
  ToolParameterInput,
  ToolType,
} from '@/interface/global';
import { LoadingOutlined } from '@ant-design/icons';
import React, { useMemo } from 'react';
import BaseCard from '../BaseCard';
import styles from '../BaseCard/index.module.less';

interface SearchFileWithResProps {
  param?: ToolParameterInput;
  output?: ToolOutputResponseEvent;
  err?: string;
  toolType?: ToolType;
}

const SearchFileWithRes: React.FC<SearchFileWithResProps> = ({
  param,
  output,
  err,
}) => {
  const filePath = useMemo(() => {
    if (!param) return '';
    if (
      param.field_name === 'fs_file_path' ||
      param.field_name === 'directory_path'
    ) {
      return param.field_content_delta;
    }
    try {
      const parsed = JSON.parse(param.field_content_delta);
      return parsed.fs_file_path || parsed.directory_path;
    } catch {
      return param.field_content_delta;
    }
  }, [param]);

  // 获取状态图标
  const getStatusIcon = () => {
    if (err)
      return (
        <span className={styles.statusIcon}>
          <AlertSVG />
        </span>
      );
    if (output) {
      return (
        <span className={styles.statusIcon}>
          <SuccessSVG />
        </span>
      );
    }
    if (param) {
      return <LoadingOutlined className={styles.statusIcon} />;
    }
    return null;
  };

  return <BaseCard filePath={filePath} statusIcon={getStatusIcon()} />;
};

export default SearchFileWithRes;
