// useAgentMessageHandlers.ts
import { ToolTypeEnum } from '@/components/AgentRender';
import { uploadTotalHistoryData } from '@/services/Api/agentic';
import { useAgenticStore } from '@/store';
import { receiveAgentMessagePayload } from '@/utils/sendAgentChat/type';
import { useCallback } from 'react';
import { AgentMsgItem } from '../type';

/**
 * 处理Agent消息的各种回调函数
 */
export const useAgentMessageHandlers = (
  chatId: string,
  sideCarIDEInfo: Record<string, any>,
  abortRef: React.MutableRefObject<() => void>,
) => {
  const { setLoading, setIsTokenOver } = useAgenticStore();

  /**
   * 处理接收到的 Agent 消息
   */
  const onReceiveAgentMessage = useCallback(
    (payload: receiveAgentMessagePayload) => {
      const {
        content,
        messageId,
        renderId,
        toolType,
        param,
        detect,
        output,
        err,
        agentErr,
      } = payload;
      if (agentErr) {
        setIsTokenOver(true);
        // 主动中断连接
        abortRef.current();
        return;
      }

      // 使用全局状态的方法更新消息
      const { msgMap: currentMsgMap, setAddData } = useAgenticStore.getState();
      const arr = Object.values(currentMsgMap);
      const existingMsg = arr.find((msg) => msg.renderId === renderId);

      if (existingMsg) {
        // @ts-ignore
        const data: AgentMsgItem = {
          content,
          toolType: toolType || existingMsg.toolType,
          param: param || existingMsg.param,
          detect: detect || existingMsg.detect,
          output: output || existingMsg.output,
          err: err || existingMsg.err,
        };
        useAgenticStore.getState().updateMessage(existingMsg.messageId, data);
        if (existingMsg.toolType === ToolTypeEnum.CODE_EDITING && output) {
          setAddData(data);
        }
      } else {
        useAgenticStore.getState().addMessage({
          chatId,
          messageId,
          type: 'agent',
          source: 'chat',
          content,
          renderId,
          toolType,
          param,
          output,
          err,
        });
      }
    },
    [chatId, setIsTokenOver, abortRef],
  );

  /**
   * 更新加载状态
   */
  const onLoadingStatusChange = useCallback(
    (status: boolean) => setLoading(status),
    [setLoading],
  );

  /**
   * 处理错误
   */
  const onError = useCallback(
    (payload: { error: string | Error; messageId: string }) => {
      const { error, messageId } = payload;
      // 使用全局状态的方法添加错误消息
      useAgenticStore.getState().addMessage({
        chatId,
        messageId,
        type: 'agent',
        source: 'chat',
        content: error?.toString() ?? '发生错误',
        renderId: messageId,
      });
    },
    [chatId],
  );

  /**
   * 请求完成后上报历史记录
   */
  const onFinally = useCallback(async () => {
    if (!sideCarIDEInfo) return;

    const { sideCarPort } = sideCarIDEInfo;
    const { msgMap, editFileList } = useAgenticStore.getState();

    uploadTotalHistoryData(
      {
        sessionId: chatId,
        uiData: JSON.stringify(msgMap),
        editFileList: editFileList,
        repoRef: `local/${sideCarIDEInfo.rootDirectory || '/'}`,
      },
      `http://localhost:${sideCarPort}`,
    ).then(({ success }) => {
      if (success) {
        console.log('历史记录上报成功');
      }
    });
  }, [chatId, sideCarIDEInfo]);

  return {
    onReceiveAgentMessage,
    onLoadingStatusChange,
    onError,
    onFinally,
  };
};
