import { useGlobalStore } from '@/store';
import classNames from 'classnames';
import styles from './index.module.less';

interface ExpandPanelTag {
  text: string;
  icon: () => React.ReactNode;
  value: any;
}

interface ExpandPanelTagListProps {
  tags: ExpandPanelTag[];
  onDelete: (index: number) => void;
}

const ExpandPanelTagList: React.FC<ExpandPanelTagListProps> = ({
  tags,
  onDelete,
}) => {
  const {
    pluginConfig: { theme },
  } = useGlobalStore();

  if (!tags.length) return null;

  return (
    <div className={classNames(styles.expandPanelTagArea, styles[theme])}>
      {tags.map((tag, index) => (
        <div key={index} className={styles.extag}>
          <div className={styles.iconWrapper}>{tag.icon()}</div>
          <span>{tag.text}</span>
          <b onClick={() => onDelete(index)}>x</b>
        </div>
      ))}
    </div>
  );
};

export default ExpandPanelTagList;
