import { ReactComponent as AlertSVG } from '@/assets/common/alert.svg';

import { ReactComponent as SuccessSVG } from '@/assets/common/file_success.svg';
import {
  ToolOutputResponseEvent,
  ToolParameterInput,
  ToolType,
} from '@/interface/global';
import parseGitDiff from '@/utils/parseGitDiff';
import { DownOutlined, LoadingOutlined } from '@ant-design/icons';
import classNames from 'classnames';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import BaseCard from '../BaseCard';
import styles from '../BaseCard/index.module.less';
import Markdown from '../Markdown';
import mdStyles from './md.module.less';

interface EditFileProps {
  param?: ToolParameterInput;
  output?: ToolOutputResponseEvent;
  err?: string;
  toolType?: ToolType;
}

const EditFile: React.FC<EditFileProps> = ({ output, param, err }) => {
  const [collapsed, setCollapsed] = useState<boolean>(false);
  const markdownRef = useRef<HTMLDivElement>(null);

  const toggleCollapse = () => setCollapsed(!collapsed);

  const filePath = useMemo(
    () =>
      param?.field_name === 'fs_file_path' ? param.field_content_delta : '',
    [param],
  );

  const code = useMemo(() => param?.optional_field, [param]);

  // Auto-scroll to bottom when code block is expanded and code is available
  useEffect(() => {
    if (!collapsed && markdownRef.current) {
      markdownRef.current.scrollTop = markdownRef.current.scrollHeight;
    }
  }, [collapsed, code]);

  const diffObj = useMemo(() => {
    try {
      if (output?.answer_up_until_now) {
        return JSON.parse(output.answer_up_until_now);
      }
    } catch (error) {
      console.log('diff 的 JSON 出错');
    }
    return null;
  }, [output]);

  const { addedLines, removedLines } = useMemo(() => {
    if (!output || !diffObj?.diff) return { addedLines: 0, removedLines: 0 };
    return parseGitDiff(diffObj.diff);
  }, [output, diffObj]);

  // 获取状态图标
  const getStatusIcon = () => {
    if (err)
      return (
        <span className={styles.statusIcon}>
          <AlertSVG />
        </span>
      );
    if (output) {
      return (
        <span className={styles.statusIcon}>
          <SuccessSVG />
        </span>
      );
    }
    if (param) {
      return <LoadingOutlined className={styles.statusIcon} />;
    }
    return null;
  };

  // 渲染统计信息
  const renderStats = () => {
    if (!output || (!addedLines && !removedLines)) return null;
    return (
      <span className={styles.extraInfo} style={{ color: '#08DA08' }}>
        +{addedLines} <span style={{ color: '#E94C6D' }}>-{removedLines}</span>
      </span>
    );
  };

  // 渲染右侧内容
  const renderRightContent = () => {
    return (
      <div
        className="box"
        onClick={(e) => {
          e.stopPropagation();
          toggleCollapse();
        }}
      >
        <DownOutlined
          className="arrowIcon"
          style={{
            transform: collapsed ? 'rotate(0deg)' : 'rotate(180deg)',
          }}
        />
      </div>
    );
  };

  // 渲染代码块
  const renderCodeBlock = () => {
    if (!code) return null;
    return (
      <div
        className={classNames(mdStyles.markdownWrapper, {
          [mdStyles.expanded]: !collapsed,
        })}
        ref={markdownRef}
      >
        <Markdown message={code} />
      </div>
    );
  };

  return (
    <BaseCard
      filePath={filePath}
      statusIcon={getStatusIcon()}
      extraLeftContent={renderStats()}
      rightContent={renderRightContent()}
      onCardClick={() => {
        // 阻止卡片点击事件，让右侧箭头可以正常点击
      }}
      clickable={false}
    >
      {renderCodeBlock()}
    </BaseCard>
  );
};

export default EditFile;
