import { ReactComponent as AlertSVG } from '@/assets/common/alert.svg';

import { ReactComponent as SuccessSVG } from '@/assets/common/file_success.svg';
import {
  ToolOutputResponseEvent,
  ToolParameterInput,
  ToolType,
} from '@/interface/global';
import { LoadingOutlined } from '@ant-design/icons';
import React, { useMemo } from 'react';
import BaseCard from '../BaseCard';
import styles from '../BaseCard/index.module.less';

interface ParseFileProps {
  param?: ToolParameterInput;
  output?: ToolOutputResponseEvent;
  err?: string;
  toolType?: ToolType;
}

const ParseFile: React.FC<ParseFileProps> = ({ param, output, err }) => {
  const filePath = useMemo(() => {
    if (!param) return null;
    return JSON.parse(param.field_content_delta).fs_file_path;
  }, [param]);

  // 解析行号区间
  const lineInfo = useMemo(() => {
    if (!param) return null;
    try {
      const delta = JSON.parse(param.field_content_delta);
      if (!delta.start_line || !delta.end_line) return null;
      return { start: delta.start_line, end: delta.end_line };
    } catch {
      return null;
    }
  }, [param]);

  // 获取状态图标
  const getStatusIcon = () => {
    if (err)
      return (
        <span className={styles.statusIcon}>
          <AlertSVG />
        </span>
      );
    if (output) {
      return (
        <span className={styles.statusIcon}>
          <SuccessSVG />
        </span>
      );
    }
    if (param?.field_name === 'fs_file_path') {
      return <LoadingOutlined className={styles.statusIcon} />;
    }
    return null;
  };

  // 只渲染lineInfo
  const renderLineInfo = () => {
    if (!lineInfo) return null;
    return (
      <span
        className={styles.extraInfo}
      >{`(L${lineInfo.start}-${lineInfo.end})`}</span>
    );
  };

  return (
    <BaseCard
      filePath={filePath}
      statusIcon={getStatusIcon()}
      extraLeftContent={renderLineInfo()}
    />
  );
};

export default ParseFile;
