import { useEffect, useState } from 'react';

export function getSearchTerm(filterValue: string, myContent: string): string {
  const prefixes = [`@${myContent}: `, `@${myContent}:`];
  for (const prefix of prefixes) {
    if (filterValue.startsWith(prefix)) {
      return filterValue.substring(prefix.length).replace(/\s+/g, '');
    }
  }
  return filterValue.replace(/\s+/g, '');
}

export function useDebounce(value: string, delay = 500) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
}

export function deepFindAll<T extends Record<string, any>>(
  arr: T[],
  callback: (node: T) => boolean,
  childrenKey: string = 'children',
): T[] {
  const results: T[] = [];

  function traverse(nodeList: T[]): void {
    for (const node of nodeList) {
      if (callback(node)) {
        results.push(node);
      }

      const children = node[childrenKey] as T[] | undefined;
      if (children && Array.isArray(children)) {
        traverse(children);
      }
    }
  }

  traverse(arr);
  return results;
}

export function flattenTree<T extends Record<string, any>>(
  arr: T[],
  childrenKey: string = 'children',
  maxDepth: number = 2,
): T[] {
  const result: T[] = [];

  function traverse(nodeList: T[], currentDepth: number): void {
    if (currentDepth > maxDepth) return;

    for (const node of nodeList) {
      result.push(node);

      const children = node[childrenKey] as T[] | undefined;
      if (children && Array.isArray(children)) {
        traverse(children, currentDepth + 1);
      }
    }
  }

  traverse(arr, 1);
  return result;
}
