import { Button, Flex } from 'antd';
import emitter from '../eventBus';
import styles from './index.module.less';

interface BottomTipsProps {
  isTokenOver: boolean;
}

const BottomTips: React.FC<BottomTipsProps> = ({ isTokenOver }) => {
  const onNewChatClick = async () => {
    return emitter.emit('clear');
  };

  if (!isTokenOver) return null;

  return (
    <Flex gap={8} justify="end" align="center">
      <span className={styles.text}>
        本轮对话 token 已达上限，开始新对话以获得更好的结果。
      </span>
      <Button size="small" type="text" onClick={onNewChatClick}>
        新建会话
      </Button>
    </Flex>
  );
};
export default BottomTips;
